window.VTCC_SITE = {"defaultLocale":"en","localeLabels":{"en":"English","es":"Español"},"localeStorageKey":"vtcc-locale","shared":{"assets":{"logo":"/assets/vtcc-logo.png","heroImage":"/assets/hero-banner.png","whoWeServeImage":"/assets/who-we-serve.png","insuranceProviders":[{"name":"Aetna Better Health","logo":"/assets/aetna.svg"},{"name":"Anthem HealthKeepers Plus","logo":"/assets/anthem-healthkeepers.svg"},{"name":"BlueCross BlueShield","logo":"/assets/blue-cross.svg"},{"name":"Cigna","logo":"/assets/cigna.svg"},{"name":"Kaiser Permanente Behavioral Health","logo":"/assets/kaiser.png"},{"name":"Molina Healthcare","logo":"/assets/molina.png"},{"name":"Optima Health","logo":"/assets/optima.png"},{"name":"UnitedHealthcare","logo":"/assets/unitedhealthcare.svg"}]},"downloads":{"abaIntake":{"file":"/assets/forms/aba-intake.pdf","type":"pdf"},"faptReferralQuestionnaire":{"file":"/assets/forms/fapt-referral-questionnaire.docx","type":"docx"},"clientRightsEnglish":{"file":"/assets/forms/client-rights-english.pdf","type":"pdf"},"clientRightsSpanish":{"file":"/assets/forms/client-rights-spanish.pdf","type":"pdf"}}},"locales":{"en":{"ui":{"languageLabel":"Language","faxLabel":"Fax","payerListTitle":"Accepted payers and funding pathways","fullPayerListLabel":"See the full list of payers and funding sources","backToResources":"Back to all resources","downloadLabel":"Download","expandAll":"Expand all","collapseAll":"Collapse all","faqSearchLabel":"Search FAQs","faqSearchPlaceholder":"Search questions and answers","faqSearchNoResults":"No FAQs match your search. Try different keywords or browse the topics below.","faqSearchResultsCount":"{count} matching questions","faqSearchInTopic":"In {topic}","menuLabel":"Menu","openMenu":"Open menu","closeMenu":"Close menu","callLabel":"Call","guidesNavLabel":"FAQs and guides","contactSwitchFamilyPrompt":"Looking for services for your family?","contactSwitchFamilyLink":"Use the family request form","contactSwitchReferralPrompt":"Submitting a professional referral?","contactSwitchReferralLink":"Use the referral inquiry form","formSubmitting":"Sending...","formSuccess":"Thank you. Your request was received. A VTCC team member will follow up.","formError":"We could not send this form. Please call VTCC or try again later.","careerFileChoose":"Choose a file","careerFileDrop":"Drop your resume or supporting document here","careerFileHint":"PDF, DOC, DOCX, or TXT. Maximum file size: 5 MB.","careerFileError":"Please choose a PDF, DOC, DOCX, or TXT file up to 5 MB.","careerFileRemove":"Remove file","careerFormSubmitting":"Preparing application...","careerFormSuccess":"Your sample application is ready. In a production version, VTCC would receive it through an approved secure process.","careerFormError":"We could not prepare the application. Please review the highlighted fields and try again."},"company":{"name":"Victoria Transcultural Clinical Center","shortName":"VTCC","tagline":"Behavioral and mental health services for diverse families"},"topBar":{"address":"10565 Fairfax Blvd Ste 300, Fairfax, VA 22030","addressHref":"https://www.google.com/maps/search/?api=1&query=10565+Fairfax+Blvd+Ste+300,+Fairfax,+VA+22030","phone":"703.218.6599","phoneHref":"tel:17032186599","email":"info@vtccmail.com","emailHref":"mailto:info@vtccmail.com"},"navigation":{"main":[{"label":"Services","href":"/#services"},{"label":"Get Started","href":"/get-started"},{"label":"Insurance","href":"/insurance"},{"label":"Referrers","href":"/referrers"},{"label":"FAQs & Guides","href":"/resources"},{"label":"About","href":"/about"},{"label":"Contact","href":"/contact"},{"label":"Careers","href":"/career"}],"utility":[{"label":"Request Services","href":"/contact","style":"cta"},{"label":"Refer a Client","href":"/referrers"},{"label":"Call Fairfax","href":"tel:17032186599"},{"label":"Call Fredericksburg","href":"tel:15404129969"}],"headerGroups":[{"label":"Services","href":"/#services"},{"label":"FAQs & Guides","links":[{"label":"Get Started","href":"/get-started"},{"label":"Insurance","href":"/insurance"},{"label":"ABA Therapy","href":"/aba"},{"label":"Early Learners","href":"/early-learners"},{"label":"Feeding Program","href":"/feeding-program"},{"label":"Social Skills Group","href":"/social-skills-group"},{"label":"FAQs & Guides","href":"/resources"}]},{"label":"For Providers","links":[{"label":"Refer a Client","href":"/referrers"}]},{"label":"About VTCC","links":[{"label":"About","href":"/about"},{"label":"Contact","href":"/contact"}]},{"label":"Careers","href":"/career"},{"label":"Forms","href":"/resources/forms"}],"headerActions":[{"label":"Request Services","href":"/contact","style":"primary"}]},"hero":{"eyebrow":"Serving children, adolescents, and families in Northern Virginia","headline":"ABA and Specialized Programs for Children and Families","headlineLead":"For children, adolescents, and families","serviceTags":["ABA Therapy","Early Learners","Feeding Program","Social Skills Group"],"subheadlineLead":"Culturally responsive behavioral and mental health services.","subheadline":"VTCC supports families through individualized ABA therapy, early learning, feeding, and advanced social skills programs.","supportingLine":"Serving families through Medicaid, managed care, commercial insurance, and county/FAPT funding pathways, pending eligibility and plan verification.","actions":[{"label":"Request Services","href":"/contact","style":"primary"},{"label":"Refer a Client","href":"/referrers","style":"secondary"},{"label":"Call VTCC","href":"tel:17032186599","style":"ghost"}]},"heroCard":{"title":"How VTCC Helps","items":["ABA therapy with individualized goals","Early Learners support for preschool-aged children","Feeding support to expand food repertoire and preferences","Social Skills Group practice for advanced peer interaction"]},"trustStrip":[{"title":"Family-centered","body":"Care plans shaped by child and caregiver needs"},{"title":"Culturally responsive","body":"Support for diverse Northern Virginia families"},{"title":"Clear next steps","body":"Intake, funding review, assessment, and treatment planning"}],"sections":{"services":{"eyebrow":"Services","title":"How VTCC helps families and referrers","intro":"Choose the path that fits your family or your referral. VTCC supports both with clear next steps.","cards":[{"label":"ABA Therapy","title":"Build meaningful skills with an individualized plan","body":"Applied Behavior Analysis helps children build meaningful skills through individualized goals, positive reinforcement, parent training, and ongoing progress monitoring.","linkLabel":"Learn about ABA","href":"/aba"},{"label":"Early Learners","title":"Prepare for school and social settings","body":"The Early Learners program helps preschool-aged children practice communication, play, routines, and early learning skills for school and social settings.","linkLabel":"Learn about Early Learners","href":"/early-learners"},{"label":"Feeding Program","title":"Expand food repertoire and preferences","body":"The Feeding Program uses ABA practices to support children as they build comfort with a wider variety of foods, tastes, textures, and mealtime routines.","linkLabel":"Learn about Feeding","href":"/feeding-program"},{"label":"Social Skills Group","title":"Practice advanced social skills with peers","body":"The Social Skills Group supports clients who are ready to practice skills such as sarcasm, conversation, flexible thinking, and age-appropriate peer play.","linkLabel":"Learn about Social Skills","href":"/social-skills-group"},{"label":"Referral Support","title":"Help families and professionals take the next step","body":"Families, schools, doctors, case managers, and county partners can contact VTCC to ask about services, eligibility, required forms, and funding next steps.","linkLabel":"Refer a client","href":"/referrers"}]},"process":{"eyebrow":"How to get started","title":"How to start services with VTCC","intro":"Starting services can feel overwhelming. Here is what to expect, step by step.","formsLinkLabel":"Intake and referral forms","formsLinkHref":"/resources/forms","steps":[{"title":"Reach out","body":"Contact VTCC by phone or through the request form."},{"title":"Review funding","body":"Tell us which service you are seeking and how the service may be funded."},{"title":"Complete intake","body":"Submit intake or referral paperwork."},{"title":"Schedule assessment","body":"VTCC reviews insurance, Medicaid, managed care, commercial coverage, or county/FAPT funding as applicable."},{"title":"Build a plan","body":"A clinical assessment or intake appointment is scheduled and an individualized treatment plan is created."},{"title":"Begin services","body":"Services begin after approval, scheduling, and required documentation are complete."}]},"aba":{"eyebrow":"ABA Therapy","title":"ABA Services","intro":"Applied Behavior Analysis uses positive techniques and principles to bring about meaningful and positive change in behavior.","topics":[{"title":"What is Applied Behavior Analysis (ABA)?","paragraphs":["Considered by many experts the gold standard therapy for autism spectrum disorder (ASD) and other developmental conditions among children, ABA focuses on gradually improving social, communication, and daily living skills using positive reinforcement.","VTCC has experienced autism specialists in Virginia who use an evidence-based approach to improve functional, social capacity, and quality of life for children and families."]},{"title":"Where can ABA be used?","paragraphs":["These techniques can be used in structured situations such as at home, during family meals, or at a neighborhood playground.","Some ABA sessions involve one-on-one interaction between the therapist and the child. Group instruction can also be useful."]},{"title":"How is ABA therapy provided to children with ASD or developmental disorders?","paragraphs":["ABA therapy provides comprehensive, individualized, and intensive early intervention programs for children with autism. These interventions are designed to begin before the age of 4 and address a full range of life skills, from communication and sociability to self-care and school readiness.","Programs often range from 20–40 hours per week for 1–3 years, depending on clinical recommendation and authorization."]},{"title":"How successful is ABA as an approach?","paragraphs":["Research and academic literature indicate ABA is one of the most effective tools available to assist children with ASD. It is a joint effort between therapists and parents to stabilize behaviors associated with ASD by reinforcing positive behaviors, strengthening communication and social skills, and training parents to communicate effectively with their children.","ABA aims to reduce symptoms, improve skills and ability, and maximize the child's function and participation in the community. It is a widely accepted treatment approach among healthcare professionals and is used globally.","ABA is tailored to the specific needs of the child based on analysis of the family and physical environment and its effects on the child's behaviors. The focus of ABA remains on improving social and communication skills and on training parents in effective management of behaviors associated with ASD. Participation and a strong alliance between parents and therapists play a crucial role in reaching milestones."]},{"title":"What is the process of receiving ABA services from VTCC?","items":["A Board-Certified Behavior Analyst (BCBA) assesses the child to determine needs, define treatment goals, and identify beneficial milestones.","Parents provide additional information about the child's abilities and areas that are difficult for them.","Based on assessment, review of reports, and parent input, the BCBA develops the treatment plan and sets initial and terminal goals.","Goals incrementally increase the skills the child needs to learn and help them function to the best of their ability.","To decrease interfering behaviors, the BCBA develops a behavior intervention plan for the child.","One or more technicians then provide treatment to the child under the supervision and direction of the BCBA.","The BCBA monitors progress across the child's goals."]},{"title":"What are some basic ABA philosophies followed at VTCC?","items":["The analyst meets regularly with family members and program staff to plan, review progress, and make adjustments as needed.","Parents and other family members and caregivers receive training so they can support learning and skill practice throughout the day.","The child's day is structured to provide many opportunities—both planned and naturally occurring—to acquire and practice skills in structured and unstructured situations.","The child receives abundant positive reinforcement for demonstrating useful skills and socially appropriate behaviors. The emphasis is on positive social interactions and enjoyable learning.","The child receives no reinforcement for behaviors that pose harm or prevent learning."]},{"title":"What kind of progress can be expected with ABA?","paragraphs":["The aim of ABA is to give the child the ability to communicate effectively and to fully function within their environment. Interventions are tailored to achieve maximum progress. Every child improves at a different pace depending on the skill areas involved.","Consistent, repeated, and intensive effort—and partnership with parents—often leads to the best outcomes from therapy."]},{"title":"Who can provide ABA services to my child or the child I am referring?","paragraphs":["In most cases, a therapist or behavior technician (BT) trained and supervised by a BCBA will provide direct therapy to your child.","The BCBA holds a post-graduate degree in psychology or behavior analysis, is certified through a national board certification exam, and holds a state license to provide treatment."]}],"columns":[{"title":"What ABA may support","items":["Communication and social interaction","Daily living routines and school readiness","Play, leisure, and independence skills","Behavior goals and safer replacement behaviors"]},{"title":"How VTCC provides ABA","items":["Assessment and treatment planning","BCBA oversight and progress monitoring","Direct therapy from trained staff as appropriate","Parent training and caregiver collaboration"]}]},"funding":{"eyebrow":"Insurance and funding","title":"Help with insurance and funding","intro":"VTCC can help families and referrers understand the funding pathways most often used for our services.","payers":["Anthem HealthKeepers Plus Medicaid of Virginia","Anthem Commercial of Virginia","Cigna","UnitedHealthcare","BlueCross BlueShield","Aetna Better Health","Molina Healthcare","Optima Health","Kaiser Permanente Behavioral Health","County/FAPT funding"],"note":"Before publishing, VTCC should confirm which plans are currently accepted, whether commercial coverage is active for each service, and which office or team member handles verification.","ctaLabel":"Check Insurance & Funding","ctaHref":"/contact"},"referrers":{"eyebrow":"For families and referrers","title":"Where would you like to start?","paths":[{"title":"For Families","body":"Learn what services may fit your child, what paperwork may be needed, and what to expect during intake.","buttonLabel":"Start as a family","buttonStyle":"primary","buttonHref":"/contact"},{"title":"For Referrers","body":"Schools, doctors, case managers, county partners, and community professionals can contact VTCC to ask about eligibility and referral requirements.","buttonLabel":"Start a referral","buttonStyle":"secondary","buttonHref":"/contact"}]},"whoWeServe":{"eyebrow":"Who we serve","title":"Support for children, adolescents, and families","intro":"VTCC serves children, adolescents, and families in Northern Virginia who may need behavioral, developmental, or mental health support.","missionStatement":"At VTCC, we understand every child is unique","items":["Autism spectrum disorder and developmental needs","Communication, social, daily living, or school-readiness skills","Early learners preparing for school and social settings","Feeding goals related to food repertoire and preferences","Advanced social skills and age-appropriate peer play","Referrals connected to Medicaid, managed care, commercial insurance, or county/FAPT funding"]},"multiculturalCare":{"eyebrow":"Multicultural care","title":"Care that respects every family's culture","body":"Every family brings its own culture, language, history, and strengths. VTCC was built to support families from diverse backgrounds with respect and collaboration. Our goal is to make services understandable, welcoming, and responsive to each family's needs."},"resources":{"eyebrow":"FAQs & Guides","title":"Find answers fast","intro":"Browse common questions about ABA therapy, our specialized programs, intake, funding, parent involvement, and referrals. Select a topic below to jump to answers.","cardLabel":"FAQ","formsPromo":{"label":"Forms","title":"Intake and referral forms","summary":"Print and complete the intake form for your service, referral questionnaires, and client rights notices.","linkLabel":"View all forms","linkHref":"/resources/forms"},"items":[{"title":"What Is ABA Therapy?","slug":"what-is-aba-therapy","summary":"How ABA works, who it may help, and what families should expect."},{"title":"What To Expect During Intake","slug":"what-to-expect-during-intake","summary":"Forms, first calls, timelines, and next steps after you reach out."},{"title":"Medicaid and FAPT Funding Basics","slug":"medicaid-fapt-funding-basics","summary":"Coverage pathways, verification, and what to prepare."},{"title":"Parent Training FAQs","slug":"parent-training-faqs","summary":"How caregivers participate in therapy and practice skills at home."},{"title":"Referrals and Eligibility","slug":"referrals-and-eligibility","summary":"Who can refer, what to send, and how VTCC responds."},{"title":"Early Learners Program","slug":"early-learners","summary":"School-readiness and social-readiness support for preschool-aged children."},{"title":"Feeding Program","slug":"feeding-program","summary":"How ABA practices can support a broader food repertoire and preferences."},{"title":"Social Skills Group","slug":"social-skills-group","summary":"Advanced social practice for conversation, sarcasm, and age-appropriate peer play."}],"categories":[{"slug":"what-is-aba-therapy","title":"What Is ABA Therapy?","intro":"Applied Behavior Analysis uses positive, individualized strategies to help children build skills that support learning, communication, and daily life.","faqs":[{"question":"What is ABA therapy?","answer":"ABA is an evidence-based approach that focuses on teaching meaningful skills and reducing behaviors that interfere with learning, safety, or daily routines. Treatment plans are individualized and adjusted as the child progresses."},{"question":"Who may benefit from ABA?","answer":"ABA is often used for children and adolescents with autism spectrum disorder or related developmental needs, but every plan depends on assessment, clinical recommendation, funding, and family goals."},{"question":"What happens during a typical ABA session?","answer":"Sessions may include structured teaching, play-based learning, communication practice, daily living routines, and caregiver coaching. Activities depend on the child's treatment plan and current goals."},{"question":"How is progress measured?","answer":"The clinical team tracks progress toward specific goals over time. Plans are reviewed regularly so strategies can be updated as skills improve or new needs emerge."},{"question":"How long does ABA last?","answer":"Length of services varies by child, funding authorization, and clinical need. Some families receive support for months, while others may continue longer depending on goals and plan approval."},{"question":"Is ABA only for young children?","answer":"No. ABA can support a wide age range depending on clinical need, funding, and service authorization. VTCC can help families understand whether ABA may be appropriate for their child."}]},{"slug":"what-to-expect-during-intake","title":"What To Expect During Intake","intro":"Intake is the process of gathering information, reviewing funding, and determining whether VTCC services are a fit.","faqs":[{"question":"How do I start the intake process?","answer":"Call VTCC or submit the request form on this site. A team member can help identify the service you need, explain paperwork, and outline funding review steps."},{"question":"What information should I have ready?","answer":"It helps to have parent or guardian contact information, the child's age, the service you are requesting, your city or county, and basic funding details such as Medicaid, MCO, commercial insurance, or county/FAPT information if known."},{"question":"What forms may be required?","answer":"Required forms depend on the service and funding source. Download the intake and referral forms from the Forms & Downloads page, or contact VTCC if you are unsure which documents apply."},{"question":"How long does intake take?","answer":"Timelines vary. Some steps move quickly after contact, while funding verification, authorization, and scheduling may take longer depending on the payer or referral source."},{"question":"What happens after I reach out?","answer":"VTCC reviews your request, confirms service and funding fit when possible, and guides you through paperwork, verification, assessment scheduling, and treatment planning."},{"question":"What if I am not sure which service I need?","answer":"That is common. Contact VTCC and describe your concerns. The team can help determine whether ABA, Early Learners, the Feeding Program, the Social Skills Group, or another pathway should be explored."}]},{"slug":"medicaid-fapt-funding-basics","title":"Medicaid and FAPT Funding Basics","intro":"Coverage questions can be confusing. These answers explain common funding pathways families and referrers ask about most often.","faqs":[{"question":"Does VTCC accept Medicaid?","answer":"VTCC's public materials reference Medicaid and managed care options. Families should contact VTCC to confirm current participation for their specific plan and service."},{"question":"What is an MCO?","answer":"A managed care organization, or MCO, administers Medicaid benefits for many Virginia families. Coverage and authorization rules may differ by plan and service type."},{"question":"What is FAPT or county funding?","answer":"Some families may access services through county or FAPT-related funding pathways. Eligibility, required documents, and approval steps vary by locality and service."},{"question":"How do I verify my coverage?","answer":"Have your insurance or funding information ready when you contact VTCC. The team can help identify what may be needed before services begin, though final approval depends on the payer or funding agency."},{"question":"What if my plan is not listed on the website?","answer":"Plan participation can change. Contact VTCC directly to ask whether your current plan or funding source may be accepted for the service you need."},{"question":"Does commercial insurance cover these services?","answer":"Commercial coverage depends on the plan, service type, and authorization requirements. VTCC can help families understand what questions to ask, but the insurance plan makes the final coverage decision."}]},{"slug":"parent-training-faqs","title":"Parent Training FAQs","intro":"Parents and caregivers are essential partners in both ABA and family-centered services.","faqs":[{"question":"Why is parent training part of ABA?","answer":"Children practice skills across daily routines at home, school, and in the community. Parent training helps caregivers use strategies consistently when therapists are not present."},{"question":"Do I need to be present during every session?","answer":"Participation expectations vary by treatment plan and funding requirements. VTCC can explain what involvement is recommended for your family."},{"question":"What if more than one caregiver supports the child?","answer":"Multiple caregivers can participate when appropriate. The clinical team may provide guidance so routines stay consistent across parents, grandparents, or other supports."},{"question":"Can parent training help between sessions?","answer":"Yes. Training often focuses on everyday moments such as transitions, communication, meals, bedtime, and community outings."},{"question":"What if English is not my first language?","answer":"VTCC was founded to support multicultural families. Ask the team about language support, translated materials, and communication options during intake."},{"question":"What if I feel overwhelmed as a caregiver?","answer":"Many families feel that way when starting services. Parent training is designed to offer practical strategies and support, not to add pressure. Tell your team what feels manageable."}]},{"slug":"referrals-and-eligibility","title":"Referrals and Eligibility","intro":"Schools, doctors, case managers, county partners, and families can all start the conversation with VTCC.","faqs":[{"question":"Who can refer to VTCC?","answer":"Families, schools, pediatricians, therapists, case managers, county partners, and other community professionals may contact VTCC to ask about services and referral requirements."},{"question":"What information should referrers include?","answer":"Helpful details often include the child's age, parent or guardian contact information, service requested, reason for referral, funding source if known, and any required referral paperwork."},{"question":"Can families refer themselves?","answer":"Yes. A parent or guardian can contact VTCC directly to ask about services, intake steps, and funding review."},{"question":"How should documents be sent?","answer":"Use only the contact methods VTCC provides for referral and intake documents. Do not send sensitive records through an unsecured form or email unless VTCC has approved a secure process."},{"question":"How quickly will VTCC respond?","answer":"Response times vary by urgency, completeness of information, and office workload. If there is an immediate safety emergency, call 911."},{"question":"Can VTCC tell me if a child is eligible before I refer?","answer":"VTCC can often discuss general service fit and required next steps, but final eligibility may depend on funding authorization, clinical assessment, and documentation."}]},{"slug":"early-learners","title":"Early Learners Program","intro":"The Early Learners program helps preschool-aged children practice skills for school and social settings.","faqs":[{"question":"What is the Early Learners program?","answer":"It is a program for preschool-aged children focused on communication, play, routines, early learning, and participation in school and social settings."},{"question":"What skills may children practice?","answer":"Goals may include transitions, following directions, communication, play, social engagement, early learning, and independence. Goals are individualized for each child."},{"question":"How are caregivers involved?","answer":"Caregivers collaborate with the team so children can practice useful skills across everyday routines and prepare for settings outside the program."}]},{"slug":"feeding-program","title":"Feeding Program","intro":"The Feeding Program uses ABA practices and positive support to help children expand food repertoire and preferences.","faqs":[{"question":"What does the Feeding Program do?","answer":"The program supports children as they practice accepting and exploring a wider variety of foods, tastes, textures, and presentations."},{"question":"How are feeding goals chosen?","answer":"Goals are individualized around the child’s current eating patterns, family priorities, and response to gradual practice and positive reinforcement."},{"question":"Are caregivers included?","answer":"Yes. Caregiver collaboration helps connect program goals with practical mealtime routines at home."}]},{"slug":"social-skills-group","title":"Social Skills Group","intro":"The Social Skills Group gives clients who are ready for advanced practice a supported setting to learn with peers.","faqs":[{"question":"Who may be a fit for the group?","answer":"The group is for clients who are ready to work on more advanced social skills and who may benefit from supported practice with peers."},{"question":"What skills may the group address?","answer":"Topics may include sarcasm, humor, conversation, flexible thinking, joining activities, problem-solving, and age-appropriate peer play."},{"question":"How are group goals individualized?","answer":"Staff provide coaching and feedback while each client works toward goals that match their current skills and social priorities."}]}]},"forms":{"eyebrow":"Forms","title":"Intake and referral forms","intro":"Select the form that applies to your service, download and print it, and return the completed document before your intake appointment.","steps":["Choose the form for your service","Download and print the form","Complete it and return it to VTCC"],"assistanceText":"Need help? Call {phone}.","insuranceTitle":"Insurance and funding","insuranceBody":"VTCC accepts clients with Medicaid or county funding. Contact your local or state Medicaid office to verify your child's coverage, or call VTCC for help with verification.","insuranceLinkLabel":"Learn about insurance and funding","insuranceLinkHref":"/insurance","categories":[{"title":"Intakes","intro":"Please download, print, and complete the intake form and questionnaire that matches the service you are requesting.","items":[{"id":"abaIntake","title":"ABA services VTCC intake form and referral source questionnaire"},{"id":"faptReferralQuestionnaire","title":"Supervised visitation and/or FAPT services referral source questionnaire"}]},{"title":"Client's rights","intro":"The safety, rights, and privacy of our clients and families are our top priority. This notice is reviewed with every client in the presence of their parents or guardians before any VTCC service begins.","items":[{"id":"clientRightsEnglish","title":"It is Your Right (English)"},{"id":"clientRightsSpanish","title":"It is Your Right (Spanish)"}]}]},"about":{"eyebrow":"About VTCC","title":"Our team and our mission","intro":"VTCC provides culturally responsive behavioral and mental health services for children, adolescents, and families across Northern Virginia.","items":["Mission and multicultural/transcultural care","Director bio and clinical leadership","BCBA/RBT or therapist bios where approved","Office locations in Fairfax and Fredericksburg"]},"contact":{"eyebrow":"Contact","title":"Request services or ask a referral question","intro":"Have questions about services, referrals, insurance, or next steps? Contact VTCC and a team member can help direct you.","callEyebrow":"Call VTCC","callTitle":"Prefer to talk with someone?","callIntro":"Choose the office that is closest to you. A team member can help with services, referral questions, and next steps."},"contactFamily":{"eyebrow":"For families","title":"Request services for your child","intro":"Tell us how to reach you and a little about your child. A VTCC team member can explain intake steps, forms, and funding review.","callEyebrow":"Call VTCC","callTitle":"Prefer to talk with someone?","callIntro":"Choose the office closest to you. A team member can help with services, paperwork, and next steps."},"contactReferral":{"eyebrow":"For referrers","title":"Start a referral or ask about eligibility","intro":"Schools, doctors, case managers, county partners, and community professionals can use this form to ask about referral requirements. Do not send protected health information here.","callEyebrow":"Call VTCC","callTitle":"Need to discuss a referral by phone?","callIntro":"Choose the office closest to the family. A team member can help with eligibility, required paperwork, and next steps."},"careers":{"eyebrow":"Careers at VTCC","title":"Bring your strengths to work that matters","intro":"Join a team that helps children, adolescents, and families move forward with care that is practical, respectful, and culturally responsive.","applyLabel":"Apply Now","applyHref":"/career/apply","overviewLabel":"Explore opportunities","pillars":[{"title":"People first","body":"We support one another so every team member can do thoughtful, dependable work."},{"title":"Culturally responsive","body":"We listen to families and colleagues, respect lived experience, and make room for different perspectives."},{"title":"Room to grow","body":"We value supervision, collaboration, and steady development at every stage of a career."}],"opportunity":{"eyebrow":"Why work with VTCC","title":"A workplace built around meaningful progress","body":"Our work is grounded in relationships. We look for people who bring professional care, curiosity, and respect to every interaction.","items":["Collaborate with a multidisciplinary team","Support children, adolescents, and families in Northern Virginia","Learn through supervision, feedback, and shared problem-solving","Contribute to a growing organization with a clear community mission"]},"steps":{"eyebrow":"What to expect","title":"A clear path from application to conversation","intro":"We want the process to feel straightforward, respectful, and worth your time.","items":[{"title":"Share your background","body":"Tell us about your experience, interests, and the kind of work you hope to do."},{"title":"Meet the team","body":"If your experience aligns with an opening, we will invite you to a conversation."},{"title":"Discuss the role","body":"We will talk through responsibilities, support, availability, and next steps."}]},"closing":{"title":"Ready to take the next step?","body":"Submit a sample application to preview the information VTCC would request from future candidates.","buttonLabel":"Apply Now"}},"earlyLearners":{"eyebrow":"Early Learners Program","title":"Build confidence for school and social settings","intro":"The Early Learners program supports preschool-aged children as they practice the routines, communication, play, and early learning skills that help them participate in school and social settings.","columns":[{"title":"What the program supports","items":["School-readiness routines and transitions","Communication and early learning skills","Play, participation, and social engagement","Following directions and building independence"]},{"title":"How families are included","items":["Individualized goals based on the child’s strengths and needs","Practice across familiar routines and settings","Caregiver collaboration and skill coaching","Progress monitoring and plan adjustments"]}]},"feedingProgram":{"eyebrow":"Feeding Program","title":"Make mealtimes more flexible and successful","intro":"The Feeding Program uses ABA practices to help children expand their food repertoire and preferences through individualized goals, positive support, and gradual practice.","columns":[{"title":"What the program may support","items":["Expanding the variety of foods a child accepts","Building comfort with new tastes, textures, and presentation","Supporting positive mealtime routines","Practicing flexible food preferences at a manageable pace"]},{"title":"How support is planned","items":["Assessment of current eating patterns and family priorities","Individualized goals and positive reinforcement","Caregiver collaboration during everyday meals","Progress monitoring and adjustments based on the child’s response"]}]},"socialSkillsGroup":{"eyebrow":"Social Skills Group","title":"Practice advanced social skills with peers","intro":"The Social Skills Group is for clients who are ready to work on more advanced social skills, including understanding sarcasm, navigating conversation, and participating in age-appropriate peer play.","columns":[{"title":"Skills the group may address","items":["Understanding sarcasm, humor, and implied meaning","Back-and-forth conversation and flexible thinking","Age-appropriate peer play and shared activities","Joining groups, solving problems, and repairing misunderstandings"]},{"title":"A supported group setting","items":["Small-group practice with individualized goals","Coaching and positive feedback from trained staff","Opportunities to practice skills in realistic interactions","Family collaboration to support carryover beyond the group"]}]}},"careerApplication":{"eyebrow":"Apply to VTCC","title":"Tell us how you could contribute","intro":"This is a front-end preview of a future application flow. Your information stays in this browser and is not sent to VTCC.","privacyTitle":"Privacy matters","privacyNote":"Do not upload clinical records, client information, Social Security numbers, or other sensitive documents. A production application portal would use an approved secure process.","selectPlaceholder":"Select one","submitLabel":"Review Application","backLabel":"Back to Careers","backHref":"/career","consentLabel":"I understand this is a preview and my information will not be submitted.","fileLabel":"Resume or supporting document","fileRequiredMessage":"Please attach a resume or supporting document.","fileTypes":".pdf,.doc,.docx,.txt","fileAcceptLabel":"Accepted file types","fields":[{"name":"fullName","label":"Full name","type":"text","autocomplete":"name"},{"name":"email","label":"Email address","type":"email","autocomplete":"email"},{"name":"phone","label":"Phone number","type":"tel","autocomplete":"tel"},{"name":"role","label":"Role of interest","type":"select","options":["Registered Behavior Technician","Board Certified Behavior Analyst","Program Clinician","Administrative or operations","Other"]},{"name":"location","label":"City and state","type":"text","autocomplete":"address-level2"},{"name":"workAuthorization","label":"Are you authorized to work in the United States?","type":"select","options":["Yes","No","I would like to discuss this"]},{"name":"experience","label":"Relevant experience","type":"textarea","rows":4},{"name":"coverLetter","label":"What interests you about working with VTCC?","type":"textarea","rows":5}]},"form":{"notice":"Please do not include private medical details, diagnosis reports, Social Security numbers, or urgent safety concerns in this form. If this is an emergency, call 911 or go to the nearest emergency room.","consentLabel":"I understand this form is not for emergencies or sensitive medical details.","submitLabel":"Submit Request","fields":[{"name":"name","label":"Parent/guardian or referrer name","type":"text","autocomplete":"name"},{"name":"email","label":"Email","type":"email","autocomplete":"email"},{"name":"phone","label":"Phone","type":"tel","autocomplete":"tel"},{"name":"preferredContact","label":"Preferred contact method","type":"select","options":["Phone","Email","Either"]},{"name":"ageRange","label":"Child's age range","type":"select","options":["0-2","3-5","6-8","9-11","12-14","15-17","18+","Not applicable"]},{"name":"service","label":"Service interest","type":"select","options":["ABA","Early Learners","Feeding Program","Social Skills Group","Not sure"]},{"name":"funding","label":"Funding source","type":"select","options":["Medicaid","MCO","Commercial insurance","County/FAPT","Not sure"]},{"name":"location","label":"City or county","type":"text"},{"name":"message","label":"Short non-sensitive message","type":"textarea","rows":4}]},"formFamily":{"notice":"Please do not include private medical details, diagnosis reports, Social Security numbers, or urgent safety concerns in this form. If this is an emergency, call 911 or go to the nearest emergency room.","consentLabel":"I understand this form is not for emergencies or sensitive medical details.","submitLabel":"Submit service request","fields":[{"name":"name","label":"Parent or guardian name","type":"text","autocomplete":"name"},{"name":"email","label":"Email","type":"email","autocomplete":"email"},{"name":"phone","label":"Phone","type":"tel","autocomplete":"tel"},{"name":"preferredContact","label":"Preferred contact method","type":"select","options":["Phone","Email","Either"]},{"name":"ageRange","label":"Child's age range","type":"select","options":["0-2","3-5","6-8","9-11","12-14","15-17","18+"]},{"name":"service","label":"Service you are interested in","type":"select","options":["ABA","Early Learners","Feeding Program","Social Skills Group","Not sure"]},{"name":"funding","label":"Funding source (if known)","type":"select","options":["Medicaid","MCO","Commercial insurance","County/FAPT","Not sure"]},{"name":"location","label":"City or county","type":"text"},{"name":"message","label":"What would you like help with?","type":"textarea","rows":4}]},"formReferral":{"notice":"Please do not include diagnosis reports, IEPs, treatment records, Social Security numbers, or urgent safety concerns in this form. Use VTCC's approved secure process for referral documents. If this is an emergency, call 911.","consentLabel":"I understand this form is for referral questions only and is not for emergencies or protected health information.","submitLabel":"Submit referral inquiry","fields":[{"name":"name","label":"Referrer name","type":"text","autocomplete":"name"},{"name":"organization","label":"Organization or agency","type":"text"},{"name":"role","label":"Your role","type":"select","options":["School staff","Physician or nurse","Therapist or counselor","Case manager","County or FAPT partner","Other community professional"]},{"name":"email","label":"Work email","type":"email","autocomplete":"email"},{"name":"phone","label":"Work phone","type":"tel","autocomplete":"tel"},{"name":"preferredContact","label":"Preferred contact method","type":"select","options":["Phone","Email","Either"]},{"name":"parentName","label":"Parent or guardian name (if known)","type":"text"},{"name":"parentPhone","label":"Parent or guardian phone (if known)","type":"tel","autocomplete":"tel"},{"name":"ageRange","label":"Child's age range","type":"select","options":["0-2","3-5","6-8","9-11","12-14","15-17","18+","Not sure"]},{"name":"service","label":"Service requested","type":"select","options":["ABA","Early Learners","Feeding Program","Social Skills Group","Not sure"]},{"name":"funding","label":"Funding source (if known)","type":"select","options":["Medicaid","MCO","Commercial insurance","County/FAPT","Not sure"]},{"name":"location","label":"Child's city or county","type":"text"},{"name":"message","label":"Reason for referral (non-sensitive summary only)","type":"textarea","rows":4}]},"offices":[{"name":"Fairfax Office","street":"10565 Fairfax Boulevard, Suite 300","city":"Fairfax, VA 22030","phone":"703.218.6599","phoneHref":"tel:17032186599","fax":"703.891.7167"},{"name":"Fredericksburg Office","street":"3920 Plank Road, Suite 220","city":"Fredericksburg, VA 22407","phone":"540.412.9969","phoneHref":"tel:15404129969","fax":"703.891.7167"}],"footer":{"text":"Victoria Transcultural Clinical Center website improvement prototype.","links":[{"label":"Services","href":"/#services"},{"label":"Insurance","href":"/insurance"},{"label":"FAQs & Guides","href":"/resources"},{"label":"Contact","href":"/contact"},{"label":"Careers","href":"/career"}]},"pages":{"abaTherapy":{"title":"ABA Therapy Page","hero":{"headline":"ABA Therapy Designed Around Each Child","body":"Applied Behavior Analysis is an evidence-based approach that uses positive strategies to help children build meaningful skills. VTCC creates individualized ABA plans based on assessment, family input, and each child's strengths and needs.","buttons":["Request ABA Services","Call About ABA"]},"sections":[{"title":"What ABA Can Support","items":["Communication","Social interaction","Daily living routines","School readiness","Play and leisure skills","Emotional and behavioral regulation","Safer replacement behaviors","Caregiver-supported skill practice at home"],"note":"Every child is different. VTCC designs goals based on assessment, observation, caregiver input, and clinical recommendations."},{"title":"How VTCC Provides ABA","steps":["A Board Certified Behavior Analyst reviews the child's needs.","The family shares information about strengths, challenges, routines, and priorities.","The BCBA creates treatment goals and a behavior support plan when appropriate.","Behavior technicians or therapists may provide direct services under BCBA supervision.","Parents and caregivers receive guidance so skills can be practiced across daily routines.","Progress is monitored and plans are updated as the child grows."]},{"title":"Parent Training","body":"Parents and caregivers are essential partners in ABA therapy. VTCC supports families with strategies they can use during everyday routines, transitions, communication moments, and challenging situations."}],"cta":{"body":"Not sure if ABA is the right fit? Contact VTCC and our team can explain the intake process, funding requirements, and next steps.","button":"Ask About ABA Services"}},"insuranceFunding":{"title":"Insurance & Funding Page","hero":{"headline":"Insurance And Funding Guidance","body":"Understanding coverage can be confusing. VTCC helps families and referral partners review available funding pathways and identify what information may be needed before services begin."},"sections":[{"title":"Funding Pathways","body":"VTCC's current public website references Medicaid, managed care organizations, commercial plans, and county/FAPT funding. Before this page is published, leadership should confirm the exact accepted plans and funding requirements for each service."},{"title":"Verification Process","intro":"Families can help by preparing:","items":["Child's full name and date of birth","Parent or guardian contact information","Insurance card or funding source","Service being requested","Referral documents, if required","Diagnosis or clinical documentation only if requested through an approved secure process"]},{"title":"Important Note","body":"Coverage and eligibility vary by service, plan, authorization requirements, and funding source. VTCC can help verify information, but final coverage decisions may depend on the insurance plan, managed care organization, or funding agency."}],"cta":"Ask About Insurance & Funding"},"forReferrers":{"title":"For Referrers Page","hero":{"headline":"Refer A Child Or Family To VTCC","body":"VTCC welcomes appropriate referrals from families, schools, pediatricians, therapists, case managers, county partners, and community professionals."},"sections":[{"title":"Referral Information To Include","intro":"To help VTCC respond efficiently, referrers may be asked for:","items":["Child or adolescent's name and age","Parent or guardian contact information","Service requested","Reason for referral","Funding source or insurance information","Relevant referral paperwork","Urgency or safety concerns, if applicable"],"note":"Do not send sensitive documents through an unsecured form or email unless VTCC has provided an approved secure method."}],"cta":{"body":"Questions about eligibility or referral fit? Contact VTCC before sending documents.","button":"Start A Referral"}},"resourcesFaq":{"title":"Resources / FAQ Page","hero":{"headline":"Resources For Families And Referral Partners","body":"VTCC offers educational resources to help families understand ABA therapy, the Early Learners program, the Feeding Program, the Social Skills Group, parent involvement, intake steps, and funding questions."},"faqs":[{"question":"What services does VTCC provide?","answer":"VTCC provides ABA therapy, an Early Learners program, a Feeding Program, and a Social Skills Group for children and families. Services depend on eligibility, funding, clinical need, and availability."},{"question":"What is the Early Learners program?","answer":"The Early Learners program is for preschool-aged children and focuses on building communication, play, routines, and early learning skills that help children participate in school and social settings."},{"question":"What does the Feeding Program support?","answer":"The Feeding Program uses ABA practices to help children gradually expand their food repertoire and preferences through individualized goals, positive support, and caregiver collaboration."},{"question":"Who may be a fit for the Social Skills Group?","answer":"The Social Skills Group is for clients who are ready to practice more advanced social skills, such as understanding sarcasm, navigating conversation, and participating in age-appropriate peer play."},{"question":"Where does VTCC provide services?","answer":"Services may be provided through individualized and group settings based on the program, treatment plan, and availability. Contact VTCC to confirm current service options for your location."},{"question":"Does VTCC accept insurance?","answer":"The current site lists several Medicaid, managed care, and commercial payers, and also references county/FAPT funding. Families should contact VTCC to verify current coverage for their plan and service."},{"question":"What is ABA therapy?","answer":"ABA is an evidence-based approach that uses positive strategies to help children build skills and reduce behaviors that interfere with learning, safety, or daily life."},{"question":"Do parents participate?","answer":"Yes. Parent and caregiver involvement is an important part of individualized services and helps children practice skills across daily routines."},{"question":"How do I get started?","answer":"Call VTCC or complete the request form. The team can explain which program may fit, required forms, funding review, intake, assessment, and scheduling."},{"question":"Can professionals refer a child?","answer":"Yes. Schools, doctors, case managers, county partners, and other professionals can contact VTCC to ask about referral requirements."}]},"earlyLearners":{"title":"Early Learners Program Page","hero":{"headline":"Early Learning Support For School And Social Readiness","body":"The Early Learners program supports preschool-aged children as they practice the routines, communication, play, and early learning skills that help them participate in school and social settings.","buttons":["Request Early Learners Services","Ask About Eligibility"]},"sections":[{"title":"What Early Learners May Practice","intro":"The Early Learners program supports preschool-aged children as they practice the routines, communication, play, and early learning skills that help them participate in school and social settings.","items":["School-readiness routines and transitions","Communication and early learning skills","Play, participation, and social engagement","Following directions and building independence"]},{"title":"Family Collaboration","body":"VTCC works with caregivers to identify meaningful goals and practice skills across everyday routines. Plans are adjusted as the child grows and gains confidence."}],"cta":{"body":"Contact VTCC to ask whether the Early Learners program may fit your preschool-aged child and to learn about the next intake steps.","button":"Ask About Early Learners"}},"feedingProgram":{"title":"Feeding Program Page","hero":{"headline":"Support For A Broader Food Repertoire","body":"The Feeding Program uses ABA practices to help children expand their food repertoire and preferences through individualized goals, positive support, and gradual practice.","buttons":["Request Feeding Program Services","Ask About Eligibility"]},"sections":[{"title":"What the Feeding Program May Support","intro":"The Feeding Program uses ABA practices to help children expand their food repertoire and preferences through individualized goals, positive support, and gradual practice.","items":["Expanding the variety of foods a child accepts","Building comfort with new tastes, textures, and presentation","Supporting positive mealtime routines","Practicing flexible food preferences at a manageable pace"]},{"title":"Individualized, Positive Practice","body":"The team partners with caregivers to set practical goals, use positive support, and introduce practice at a pace that respects the child’s needs and family routines."}],"cta":{"body":"Contact VTCC to ask whether the Feeding Program may be appropriate for your child and to learn about the intake process.","button":"Ask About the Feeding Program"}},"socialSkillsGroup":{"title":"Social Skills Group Page","hero":{"headline":"Build More Advanced Social Skills With Peers","body":"The Social Skills Group is for clients who are ready to work on more advanced social skills, including understanding sarcasm, navigating conversation, and participating in age-appropriate peer play.","buttons":["Request Social Skills Group Services","Ask About Eligibility"]},"sections":[{"title":"What the Group May Practice","intro":"The Social Skills Group is for clients who are ready to work on more advanced social skills, including understanding sarcasm, navigating conversation, and participating in age-appropriate peer play.","items":["Understanding sarcasm, humor, and implied meaning","Back-and-forth conversation and flexible thinking","Age-appropriate peer play and shared activities","Joining groups, solving problems, and repairing misunderstandings"]},{"title":"Learning Through Supported Practice","body":"Clients receive coaching and feedback while practicing realistic interactions with peers. Group goals are individualized and designed to support carryover into school, community, and social settings."}],"cta":{"body":"Contact VTCC to ask whether the Social Skills Group may be a fit for your child and to learn about current group availability.","button":"Ask About Social Skills Group"}}},"compliance":{"contentApproval":"Leadership should review and approve all final service, eligibility, insurance, and compliance language.","formSecurity":"Do not collect diagnosis reports, clinical details, or protected health information through a normal contact form unless VTCC confirms the form is secure, approved, and compliant."},"home":{"processTeaser":{"linkLabel":"See the full intake path","linkHref":"/get-started"},"resourcesTeaser":{"title":"Helpful guides and FAQs","intro":"Explore common topics about intake, funding, ABA therapy, specialized programs, and referrals.","linkLabel":"Browse FAQs & guides","linkHref":"/resources"}}},"es":{"ui":{"languageLabel":"Idioma","faxLabel":"Fax","payerListTitle":"Pagadores aceptados y vías de financiamiento","fullPayerListLabel":"Ver la lista completa de pagadores y fuentes de financiamiento","backToResources":"Volver a todos los recursos","downloadLabel":"Descargar","expandAll":"Expandir todo","collapseAll":"Contraer todo","faqSearchLabel":"Search FAQs","faqSearchPlaceholder":"Search questions and answers","faqSearchNoResults":"No FAQs match your search. Try different keywords or browse the topics below.","faqSearchResultsCount":"{count} matching questions","faqSearchInTopic":"In {topic}","menuLabel":"Menu","openMenu":"Open menu","closeMenu":"Close menu","callLabel":"Call","guidesNavLabel":"Preguntas y guías","contactSwitchFamilyPrompt":"Looking for services for your family?","contactSwitchFamilyLink":"Use the family request form","contactSwitchReferralPrompt":"Submitting a professional referral?","contactSwitchReferralLink":"Use the referral inquiry form","formSubmitting":"Sending...","formSuccess":"Thank you. Your request was received. A VTCC team member will follow up.","formError":"We could not send this form. Please call VTCC or try again later.","careerFileChoose":"Elegir un archivo","careerFileDrop":"Suelte aquí su currículum o documento de apoyo","careerFileHint":"PDF, DOC, DOCX o TXT. Tamaño máximo: 5 MB.","careerFileError":"Elija un archivo PDF, DOC, DOCX o TXT de hasta 5 MB.","careerFileRemove":"Eliminar archivo","careerFormSubmitting":"Preparando la solicitud...","careerFormSuccess":"Su solicitud de muestra está lista. En una versión de producción, VTCC la recibiría mediante un proceso seguro aprobado.","careerFormError":"No pudimos preparar la solicitud. Revise los campos marcados e inténtelo de nuevo."},"company":{"name":"Victoria Transcultural Clinical Center","shortName":"VTCC","tagline":"Servicios de salud mental y conductual para familias diversas"},"topBar":{"address":"10565 Fairfax Blvd Ste 300, Fairfax, VA 22030","addressHref":"https://www.google.com/maps/search/?api=1&query=10565+Fairfax+Blvd+Ste+300,+Fairfax,+VA+22030","phone":"703.218.6599","phoneHref":"tel:17032186599","email":"info@vtccmail.com","emailHref":"mailto:info@vtccmail.com"},"navigation":{"main":[{"label":"Servicios","href":"/#services"},{"label":"Comenzar","href":"/get-started"},{"label":"Seguro","href":"/insurance"},{"label":"Referentes","href":"/referrers"},{"label":"Preguntas y Guías","href":"/resources"},{"label":"Acerca de","href":"/about"},{"label":"Contacto","href":"/contact"},{"label":"Carreras","href":"/career"}],"utility":[{"label":"Solicitar Servicios","href":"/contact","style":"cta"},{"label":"Referir un Cliente","href":"/referrers"},{"label":"Llamar a Fairfax","href":"tel:17032186599"},{"label":"Llamar a Fredericksburg","href":"tel:15404129969"}],"headerGroups":[{"label":"Servicios","href":"/#services"},{"label":"Preguntas y Guías","links":[{"label":"Comenzar","href":"/get-started"},{"label":"Seguro","href":"/insurance"},{"label":"Terapia ABA","href":"/aba"},{"label":"Programa de Primeros Aprendices","href":"/early-learners"},{"label":"Programa de Alimentación","href":"/feeding-program"},{"label":"Grupo de Habilidades Sociales","href":"/social-skills-group"},{"label":"Preguntas y Guías","href":"/resources"}]},{"label":"Para proveedores","links":[{"label":"Referir un cliente","href":"/referrers"}]},{"label":"Acerca de VTCC","links":[{"label":"Acerca de","href":"/about"},{"label":"Contacto","href":"/contact"}]},{"label":"Carreras","href":"/career"},{"label":"Formularios","href":"/resources/forms"}],"headerActions":[{"label":"Solicitar servicios","href":"/contact","style":"primary"}]},"hero":{"eyebrow":"Atendiendo a niños, adolescentes y familias en el norte de Virginia","headline":"ABA y programas especializados para niños y familias","headlineLead":"For children, adolescents, and families","serviceTags":["ABA Therapy","Early Learners","Feeding Program","Social Skills Group"],"subheadlineLead":"Culturally responsive behavioral and mental health services.","subheadline":"Victoria Transcultural Clinical Center ofrece servicios conductuales y de salud mental culturalmente responsivos para niños, adolescentes y familias. Nuestro equipo apoya a las familias mediante terapia ABA individualizada, programas especializados, colaboración con padres y orientación sobre financiamiento.","supportingLine":"Atendemos a familias a través de Medicaid, organizaciones de atención administrada, seguros comerciales y vías de financiamiento del condado/FAPT, sujeto a elegibilidad y verificación del plan.","actions":[{"label":"Solicitar Servicios","href":"/contact","style":"primary"},{"label":"Referir un Cliente","href":"/referrers","style":"secondary"},{"label":"Llamar a VTCC","href":"tel:17032186599","style":"ghost"}]},"heroCard":{"title":"Cómo ayuda VTCC","items":["Terapia ABA con metas individualizadas","Programas especializados para las necesidades de cada niño","Orientación sobre Medicaid, MCO, seguros comerciales y FAPT pendiente de verificación","Recursos en inglés y español"]},"trustStrip":[{"title":"Centrado en la familia","body":"Planes de atención adaptados a las necesidades del niño y del cuidador"},{"title":"Culturalmente responsivo","body":"Apoyo para familias diversas del norte de Virginia"},{"title":"Pasos claros","body":"Admisión, revisión de financiamiento, evaluación y planificación del tratamiento"}],"sections":{"services":{"eyebrow":"Servicios","title":"Cómo VTCC apoya a familias y referentes","intro":"Elija la opción que mejor le sirva: somos familia o referente. VTCC apoya a ambos con pasos claros.","cards":[{"label":"Terapia ABA","title":"Desarrolle habilidades significativas con un plan individualizado","body":"El Análisis de Conducta Aplicado ayuda a los niños a desarrollar habilidades significativas mediante metas individualizadas, refuerzo positivo, capacitación para padres y monitoreo continuo del progreso.","linkLabel":"Conozca la ABA","href":"/aba"},{"label":"Primeros Aprendices","title":"Prepárese para la escuela y los entornos sociales","body":"El programa de Primeros Aprendices ayuda a niños en edad preescolar a practicar comunicación, juego, rutinas y habilidades de aprendizaje temprano para la escuela y los entornos sociales.","linkLabel":"Conozca Primeros Aprendices","href":"/early-learners"},{"label":"Programa de Alimentación","title":"Amplíe el repertorio y las preferencias alimentarias","body":"El Programa de Alimentación utiliza prácticas ABA para apoyar a los niños mientras desarrollan comodidad con una mayor variedad de alimentos, sabores, texturas y rutinas de comida.","linkLabel":"Conozca el programa de alimentación","href":"/feeding-program"},{"label":"Grupo de Habilidades Sociales","title":"Practique habilidades sociales avanzadas con compañeros","body":"El Grupo de Habilidades Sociales apoya a clientes que están listos para practicar sarcasmo, conversación, pensamiento flexible y juego apropiado para su edad con compañeros.","linkLabel":"Conozca el grupo social","href":"/social-skills-group"},{"label":"Apoyo de Referencias","title":"Ayude a familias y profesionales a dar el siguiente paso","body":"Familias, escuelas, médicos, administradores de casos y socios del condado pueden contactar a VTCC para preguntar sobre servicios, elegibilidad, formularios requeridos y pasos de financiamiento.","linkLabel":"Referir un cliente","href":"/referrers"}]},"process":{"eyebrow":"Cómo comenzar","title":"Cómo iniciar servicios con VTCC","intro":"Comenzar servicios puede resultar abrumador. Esto es lo que puede esperar, paso a paso.","formsLinkLabel":"Descargar formularios de admisión","formsLinkHref":"/resources/forms","steps":[{"title":"Comuníquese","body":"Contacte a VTCC por teléfono o mediante el formulario de solicitud."},{"title":"Revise el financiamiento","body":"Indíquenos qué servicio busca y cómo puede financiarse."},{"title":"Complete la admisión","body":"Envíe la documentación de admisión o referencia."},{"title":"Programe la evaluación","body":"VTCC revisa seguro, Medicaid, atención administrada, cobertura comercial o financiamiento del condado/FAPT según corresponda."},{"title":"Elabore un plan","body":"Se programa una evaluación clínica o cita de admisión y se crea un plan de tratamiento individualizado."},{"title":"Comience los servicios","body":"Los servicios comienzan después de la aprobación, programación y documentación requerida."}]},"aba":{"eyebrow":"Terapia ABA","title":"Servicios de ABA","intro":"El Análisis de Conducta Aplicado utiliza técnicas y principios positivos para lograr cambios conductuales significativos y positivos.","topics":[{"title":"¿Qué es el Análisis de Conducta Aplicado (ABA)?","paragraphs":["Considerado por muchos expertos como la terapia estándar de referencia para el trastorno del espectro autista (TEA) y otras afecciones del desarrollo en niños, la ABA se centra en mejorar gradualmente las habilidades sociales, de comunicación y de la vida diaria mediante refuerzo positivo.","VTCC cuenta con especialistas en autismo en Virginia que utilizan un enfoque basado en evidencia para mejorar la capacidad funcional y social y la calidad de vida de los niños y las familias."]},{"title":"¿Dónde se puede utilizar la ABA?","paragraphs":["Estas técnicas pueden utilizarse en situaciones estructuradas como en el hogar, durante las comidas familiares o en un parque del vecindario.","Algunas sesiones de ABA implican interacción individual entre el terapeuta y el niño. La instrucción grupal también puede ser útil."]},{"title":"¿Cómo se brinda la terapia ABA a niños con TEA o trastornos del desarrollo?","paragraphs":["La terapia ABA ofrece programas integrales, individualizados e intensivos de intervención temprana para niños con autismo. Estas intervenciones están diseñadas para comenzar antes de los 4 años y abordan un amplio rango de habilidades para la vida, desde la comunicación y la sociabilidad hasta el autocuidado y la preparación escolar.","Los programas suelen oscilar entre 20 y 40 horas por semana durante 1 a 3 años, según la recomendación clínica y la autorización."]},{"title":"¿Qué tan exitoso es la ABA como enfoque?","paragraphs":["La investigación y la literatura académica indican que la ABA es una de las herramientas más eficaces disponibles para ayudar a niños con TEA. Es un esfuerzo conjunto entre terapeutas y padres para estabilizar conductas asociadas con el TEA mediante el refuerzo de conductas positivas, el fortalecimiento de habilidades de comunicación y socialización, y la capacitación de los padres para comunicarse eficazmente con sus hijos.","La ABA busca reducir síntomas, mejorar habilidades y capacidades, y maximizar la función y participación del niño en la comunidad. Es un enfoque ampliamente aceptado entre profesionales de la salud y se utiliza a nivel global.","La ABA se adapta a las necesidades específicas del niño según el análisis del entorno familiar y físico y sus efectos en las conductas del niño. El enfoque de la ABA sigue centrado en mejorar las habilidades sociales y de comunicación y en capacitar a los padres para gestionar eficazmente las conductas asociadas con el TEA. La participación y una alianza sólida entre padres y terapeutas desempeñan un papel crucial para alcanzar los hitos."]},{"title":"¿Cuál es el proceso para recibir servicios de ABA de VTCC?","items":["Un Analista de Conducta Certificado por la Junta (BCBA) evalúa al niño para determinar necesidades, definir metas de tratamiento e identificar hitos beneficiosos.","Los padres proporcionan información adicional sobre las habilidades del niño y las áreas que le resultan difíciles.","Según la evaluación, la revisión de informes y la aportación de los padres, el BCBA desarrolla el plan de tratamiento y establece metas iniciales y finales.","Las metas aumentan incrementalmente las habilidades que el niño necesita aprender y le ayudan a funcionar lo mejor posible.","Para disminuir conductas que interfieren, el BCBA desarrolla un plan de intervención conductual para el niño.","Uno o más técnicos brindan tratamiento al niño bajo la supervisión y dirección del BCBA.","El BCBA monitorea el progreso en las metas del niño."]},{"title":"¿Cuáles son algunas filosofías básicas de ABA que sigue VTCC?","items":["El analista se reúne regularmente con familiares y personal del programa para planificar, revisar el progreso y hacer ajustes según sea necesario.","Los padres y otros familiares y cuidadores reciben capacitación para apoyar el aprendizaje y la práctica de habilidades durante el día.","El día del niño se estructura para ofrecer muchas oportunidades, planificadas y naturales, de adquirir y practicar habilidades en situaciones estructuradas y no estructuradas.","El niño recibe abundante refuerzo positivo por demostrar habilidades útiles y conductas socialmente apropiadas. El énfasis está en interacciones sociales positivas y un aprendizaje agradable.","El niño no recibe refuerzo por conductas que causan daño o impiden el aprendizaje."]},{"title":"¿Qué tipo de progreso se puede esperar con la ABA?","paragraphs":["El objetivo de la ABA es dar al niño la capacidad de comunicarse eficazmente y funcionar plenamente en su entorno. Las intervenciones se adaptan para lograr el máximo progreso. Cada niño mejora a un ritmo diferente según las áreas de habilidad involucradas.","Un esfuerzo consistente, repetido e intenso, junto con la colaboración de los padres, suele conducir a los mejores resultados de la terapia."]},{"title":"¿Quién puede brindar servicios de ABA a mi hijo o al niño que estoy refiriendo?","paragraphs":["En la mayoría de los casos, un terapeuta o técnico de conducta (BT) capacitado y supervisado por un BCBA brindará terapia directa a su hijo.","El BCBA tiene un título de posgrado en psicología o análisis de conducta, está certificado mediante un examen nacional de certificación y cuenta con licencia estatal para brindar tratamiento."]}],"columns":[{"title":"Lo que la ABA puede apoyar","items":["Comunicación e interacción social","Rutinas de vida diaria y preparación escolar","Habilidades de juego, ocio e independencia","Metas conductuales y comportamientos de reemplazo más seguros"]},{"title":"Cómo VTCC brinda ABA","items":["Evaluación y planificación del tratamiento","Supervisión BCBA y monitoreo del progreso","Terapia directa del personal capacitado según corresponda","Capacitación para padres y colaboración con cuidadores"]}]},"funding":{"eyebrow":"Seguro y financiamiento","title":"Ayuda con el seguro y el financiamiento","intro":"VTCC puede ayudar a familias y referentes a entender las vías de financiamiento más comunes para nuestros servicios.","payers":["Anthem HealthKeepers Plus Medicaid of Virginia","Anthem Commercial of Virginia","Cigna","UnitedHealthcare","BlueCross BlueShield","Aetna Better Health","Molina Healthcare","Optima Health","Kaiser Permanente Behavioral Health","Financiamiento del condado/FAPT"],"note":"Antes de publicar, VTCC debe confirmar qué planes se aceptan actualmente, si la cobertura comercial está activa para cada servicio y qué oficina o miembro del equipo maneja la verificación.","ctaLabel":"Consultar seguro y financiamiento","ctaHref":"/contact"},"referrers":{"eyebrow":"Para familias y referentes","title":"¿Por dónde quiere empezar?","paths":[{"title":"Para Familias","body":"Conozca qué servicios pueden ser adecuados para su hijo, qué documentación puede necesitarse y qué esperar durante la admisión.","buttonLabel":"Comenzar como familia","buttonStyle":"primary","buttonHref":"/contact"},{"title":"Para Referentes","body":"Escuelas, médicos, administradores de casos, socios del condado y profesionales comunitarios pueden contactar a VTCC para preguntar sobre elegibilidad y requisitos de referencia.","buttonLabel":"Iniciar una referencia","buttonStyle":"secondary","buttonHref":"/contact"}]},"whoWeServe":{"eyebrow":"A quién servimos","title":"Apoyo para niños, adolescentes y familias","intro":"VTCC atiende a niños, adolescentes y familias en el norte de Virginia que pueden necesitar apoyo conductual, del desarrollo o de salud mental.","missionStatement":"At VTCC, we understand every child is unique","items":["Trastorno del espectro autista y necesidades del desarrollo","Habilidades de comunicación, sociales, vida diaria o preparación escolar","Dificultades conductuales o emocionales significativas","Estrés familiar relacionado con las necesidades de cuidado del niño","Niños pequeños que se preparan para la escuela y los entornos sociales","Metas de alimentación relacionadas con el repertorio y las preferencias alimentarias","Habilidades sociales avanzadas y juego apropiado para la edad con compañeros","Referencias conectadas con Medicaid, atención administrada, seguro comercial o financiamiento del condado/FAPT"]},"multiculturalCare":{"eyebrow":"Atención multicultural","title":"Atención que respeta la cultura de cada familia","body":"Cada familia aporta su propia cultura, idioma, historia y fortalezas. VTCC fue creado para apoyar a familias de diversos orígenes con respeto y colaboración. Nuestro objetivo es que los servicios sean comprensibles, acogedores y adaptados a las necesidades de cada familia."},"resources":{"eyebrow":"Preguntas y Guías","title":"Encuentre respuestas rápidamente","intro":"Explore preguntas comunes sobre terapia ABA, nuestros programas especializados, admisión, financiamiento, participación de padres y referencias. Seleccione un tema a continuación para ver respuestas.","cardLabel":"Pregunta frecuente","formsPromo":{"label":"Formularios","title":"Formularios de admisión y referencia","summary":"Imprima y complete el formulario de admisión para su servicio, cuestionarios de referencia y avisos de derechos del cliente.","linkLabel":"Ver todos los formularios","linkHref":"/resources/forms"},"items":[{"title":"¿Qué es la Terapia ABA?","slug":"what-is-aba-therapy","summary":"Cómo funciona la ABA, a quién puede ayudar y qué deben esperar las familias."},{"title":"Qué Esperar Durante la Admisión","slug":"what-to-expect-during-intake","summary":"Formularios, primeras llamadas, plazos y próximos pasos después de contactarnos."},{"title":"Conceptos Básicos de Medicaid y Financiamiento FAPT","slug":"medicaid-fapt-funding-basics","summary":"Vías de cobertura, verificación y qué preparar."},{"title":"Preguntas Frecuentes sobre Capacitación para Padres","slug":"parent-training-faqs","summary":"Cómo participan los cuidadores en la terapia y practican habilidades en casa."},{"title":"Referencias y Elegibilidad","slug":"referrals-and-eligibility","summary":"Quién puede referir, qué enviar y cómo responde VTCC."},{"title":"Programa de Primeros Aprendices","slug":"early-learners","summary":"Apoyo para la preparación escolar y social de niños en edad preescolar."},{"title":"Programa de Alimentación","slug":"feeding-program","summary":"Cómo las prácticas ABA pueden apoyar un repertorio y preferencias alimentarias más amplios."},{"title":"Grupo de Habilidades Sociales","slug":"social-skills-group","summary":"Práctica social avanzada para conversación, sarcasmo y juego apropiado para la edad con compañeros."}],"categories":[{"slug":"what-is-aba-therapy","title":"¿Qué es la Terapia ABA?","intro":"El Análisis de Conducta Aplicado utiliza estrategias positivas e individualizadas para ayudar a los niños a desarrollar habilidades que apoyan el aprendizaje, la comunicación y la vida diaria.","faqs":[{"question":"¿Qué es la terapia ABA?","answer":"La ABA es un enfoque basado en evidencia que se centra en enseñar habilidades significativas y reducir conductas que interfieren con el aprendizaje, la seguridad o las rutinas diarias. Los planes de tratamiento son individualizados y se ajustan a medida que el niño progresa."},{"question":"¿Quién puede beneficiarse de la ABA?","answer":"La ABA se utiliza con frecuencia para niños y adolescentes con trastorno del espectro autista o necesidades del desarrollo relacionadas, pero cada plan depende de la evaluación, la recomendación clínica, el financiamiento y las metas familiares."},{"question":"¿Qué ocurre durante una sesión típica de ABA?","answer":"Las sesiones pueden incluir enseñanza estructurada, aprendizaje basado en el juego, práctica de comunicación, rutinas de vida diaria y orientación para cuidadores. Las actividades dependen del plan de tratamiento y de las metas actuales del niño."},{"question":"¿Cómo se mide el progreso?","answer":"El equipo clínico hace seguimiento del progreso hacia metas específicas con el tiempo. Los planes se revisan con regularidad para que las estrategias puedan actualizarse a medida que mejoran las habilidades o surgen nuevas necesidades."},{"question":"¿Cuánto dura la ABA?","answer":"La duración varía según el niño, la autorización de financiamiento y la necesidad clínica. Algunas familias reciben apoyo durante meses, mientras que otras pueden continuar más tiempo según las metas y la aprobación del plan."},{"question":"¿La ABA es solo para niños pequeños?","answer":"No. La ABA puede apoyar una amplia variedad de edades según la necesidad clínica, el financiamiento y la autorización del servicio. VTCC puede ayudar a las familias a entender si la ABA puede ser apropiada para su hijo."}]},{"slug":"what-to-expect-during-intake","title":"Qué Esperar Durante la Admisión","intro":"La admisión es el proceso de recopilar información, revisar el financiamiento y determinar si los servicios de VTCC son adecuados.","faqs":[{"question":"¿Cómo inicio el proceso de admisión?","answer":"Llame a VTCC o envíe el formulario de solicitud en este sitio. Un miembro del equipo puede ayudar a identificar el servicio que necesita, explicar la documentación y describir los pasos de revisión de financiamiento."},{"question":"¿Qué información debo tener lista?","answer":"Ayuda tener información de contacto del padre o tutor, la edad del niño, el servicio solicitado, su ciudad o condado y detalles básicos de financiamiento como Medicaid, MCO, seguro comercial o información del condado/FAPT si la conoce."},{"question":"¿Qué formularios pueden ser necesarios?","answer":"Los formularios requeridos dependen del servicio y de la fuente de financiamiento. Descargue los formularios de admisión y referencia en la página de Formularios, o contacte a VTCC si no está seguro de qué documentos aplican."},{"question":"¿Cuánto tarda la admisión?","answer":"Los plazos varían. Algunos pasos avanzan rápidamente después del contacto, mientras que la verificación de financiamiento, la autorización y la programación pueden tardar más según el pagador o la fuente de referencia."},{"question":"¿Qué ocurre después de que me comunico?","answer":"VTCC revisa su solicitud, confirma la compatibilidad del servicio y del financiamiento cuando es posible, y le guía a través de la documentación, la verificación, la programación de evaluaciones y la planificación del tratamiento."},{"question":"¿Qué pasa si no estoy seguro de qué servicio necesito?","answer":"Es muy común. Contacte a VTCC y describa sus inquietudes. El equipo puede ayudar a determinar si deben explorarse la ABA, Primeros Aprendices, el Programa de Alimentación, el Grupo de Habilidades Sociales u otra vía."}]},{"slug":"medicaid-fapt-funding-basics","title":"Conceptos Básicos de Medicaid y Financiamiento FAPT","intro":"Las preguntas sobre cobertura pueden resultar confusas. Estas respuestas explican las vías de financiamiento que las familias y referentes preguntan con más frecuencia.","faqs":[{"question":"¿VTCC acepta Medicaid?","answer":"Los materiales públicos de VTCC hacen referencia a Medicaid y opciones de atención administrada. Las familias deben contactar a VTCC para confirmar la participación actual para su plan y servicio específicos."},{"question":"¿Qué es un MCO?","answer":"Una organización de atención administrada, o MCO, administra los beneficios de Medicaid para muchas familias de Virginia. Las reglas de cobertura y autorización pueden diferir según el plan y el tipo de servicio."},{"question":"¿Qué es FAPT o financiamiento del condado?","answer":"Algunas familias pueden acceder a servicios a través de vías de financiamiento del condado o relacionadas con FAPT. La elegibilidad, los documentos requeridos y los pasos de aprobación varían según la localidad y el servicio."},{"question":"¿Cómo verifico mi cobertura?","answer":"Tenga lista su información de seguro o financiamiento cuando contacte a VTCC. El equipo puede ayudar a identificar qué puede necesitarse antes de que comiencen los servicios, aunque la aprobación final depende del pagador o agencia de financiamiento."},{"question":"¿Qué pasa si mi plan no aparece en el sitio web?","answer":"La participación de planes puede cambiar. Contacte directamente a VTCC para preguntar si su plan o fuente de financiamiento actual puede ser aceptado para el servicio que necesita."},{"question":"¿El seguro comercial cubre estos servicios?","answer":"La cobertura comercial depende del plan, del tipo de servicio y de los requisitos de autorización. VTCC puede ayudar a las familias a entender qué preguntas hacer, pero el plan de seguros toma la decisión final de cobertura."}]},{"slug":"parent-training-faqs","title":"Preguntas Frecuentes sobre Capacitación para Padres","intro":"Los padres y cuidadores son socios esenciales tanto en la ABA como en los servicios centrados en la familia.","faqs":[{"question":"¿Por qué la capacitación para padres forma parte de la ABA?","answer":"Los niños practican habilidades en rutinas diarias en casa, la escuela y la comunidad. La capacitación para padres ayuda a los cuidadores a usar estrategias de forma consistente cuando los terapeutas no están presentes."},{"question":"¿Debo estar presente en cada sesión?","answer":"Las expectativas de participación varían según el plan de tratamiento y los requisitos de financiamiento. VTCC puede explicar qué nivel de participación se recomienda para su familia."},{"question":"¿Qué pasa si más de un cuidador apoya al niño?","answer":"Varios cuidadores pueden participar cuando sea apropiado. El equipo clínico puede ofrecer orientación para que las rutinas se mantengan consistentes entre padres, abuelos u otros apoyos."},{"question":"¿La capacitación para padres ayuda entre sesiones?","answer":"Sí. La capacitación a menudo se centra en momentos cotidianos como transiciones, comunicación, comidas, hora de dormir y salidas a la comunidad."},{"question":"¿Qué pasa si el inglés no es mi primer idioma?","answer":"VTCC fue fundado para apoyar a familias multiculturales. Pregunte al equipo sobre apoyo lingüístico, materiales traducidos y opciones de comunicación durante la admisión."},{"question":"¿Qué pasa si me siento abrumado como cuidador?","answer":"Muchas familias se sienten así al comenzar servicios. La capacitación para padres está diseñada para ofrecer estrategias prácticas y apoyo, no para aumentar la presión. Dígale a su equipo qué le resulta manejable."}]},{"slug":"referrals-and-eligibility","title":"Referencias y Elegibilidad","intro":"Escuelas, médicos, administradores de casos, socios del condado y familias pueden iniciar la conversación con VTCC.","faqs":[{"question":"¿Quién puede referir a VTCC?","answer":"Familias, escuelas, pediatras, terapeutas, administradores de casos, socios del condado y otros profesionales comunitarios pueden contactar a VTCC para preguntar sobre servicios y requisitos de referencia."},{"question":"¿Qué información deben incluir los referentes?","answer":"Los detalles útiles suelen incluir la edad del niño, información de contacto del padre o tutor, servicio solicitado, motivo de la referencia, fuente de financiamiento si se conoce y cualquier documentación de referencia requerida."},{"question":"¿Pueden las familias referirse a sí mismas?","answer":"Sí. Un padre o tutor puede contactar directamente a VTCC para preguntar sobre servicios, pasos de admisión y revisión de financiamiento."},{"question":"¿Cómo deben enviarse los documentos?","answer":"Use solo los métodos de contacto que VTCC proporciona para documentos de referencia y admisión. No envíe registros sensibles a través de un formulario o correo no seguro a menos que VTCC haya aprobado un proceso seguro."},{"question":"¿Qué tan rápido responderá VTCC?","answer":"Los tiempos de respuesta varían según la urgencia, la completitud de la información y la carga de trabajo de la oficina. Si hay una emergencia de seguridad inmediata, llame al 911."},{"question":"¿Puede VTCC decirme si un niño es elegible antes de referir?","answer":"VTCC a menudo puede discutir la compatibilidad general del servicio y los próximos pasos requeridos, pero la elegibilidad final puede depender de la autorización de financiamiento, la evaluación clínica y la documentación."}]},{"slug":"early-learners","title":"Programa de Primeros Aprendices","intro":"El programa de Primeros Aprendices ayuda a niños en edad preescolar a practicar habilidades para la escuela y los entornos sociales.","faqs":[{"question":"¿Qué es el programa de Primeros Aprendices?","answer":"Es un programa para niños en edad preescolar que se enfoca en comunicación, juego, rutinas, aprendizaje temprano y participación en la escuela y en entornos sociales."},{"question":"¿Qué habilidades pueden practicar los niños?","answer":"Las metas pueden incluir transiciones, seguir instrucciones, comunicación, juego, conexión social, aprendizaje temprano e independencia. Las metas son individualizadas para cada niño."},{"question":"¿Cómo participan los cuidadores?","answer":"Los cuidadores colaboran con el equipo para que los niños practiquen habilidades útiles en las rutinas diarias y se preparen para entornos fuera del programa."}]},{"slug":"feeding-program","title":"Programa de Alimentación","intro":"El Programa de Alimentación utiliza prácticas ABA y apoyo positivo para ayudar a los niños a ampliar su repertorio y sus preferencias alimentarias.","faqs":[{"question":"¿Qué hace el Programa de Alimentación?","answer":"El programa apoya a los niños mientras practican aceptar y explorar una mayor variedad de alimentos, sabores, texturas y presentaciones."},{"question":"¿Cómo se eligen las metas de alimentación?","answer":"Las metas se individualizan según los patrones actuales de alimentación del niño, las prioridades familiares y su respuesta a la práctica gradual y al refuerzo positivo."},{"question":"¿Se incluye a los cuidadores?","answer":"Sí. La colaboración con los cuidadores ayuda a conectar las metas del programa con rutinas prácticas de comida en el hogar."}]},{"slug":"social-skills-group","title":"Grupo de Habilidades Sociales","intro":"El Grupo de Habilidades Sociales brinda a clientes que están listos para practicar habilidades avanzadas un entorno con apoyo para aprender con compañeros.","faqs":[{"question":"¿Quién puede beneficiarse del grupo?","answer":"El grupo es para clientes que están listos para trabajar en habilidades sociales más avanzadas y que pueden beneficiarse de la práctica con apoyo junto a compañeros."},{"question":"¿Qué habilidades puede abordar el grupo?","answer":"Los temas pueden incluir sarcasmo, humor, conversación, pensamiento flexible, unirse a actividades, resolución de problemas y juego apropiado para la edad con compañeros."},{"question":"¿Cómo se individualizan las metas del grupo?","answer":"El personal ofrece orientación y comentarios mientras cada cliente trabaja en metas que corresponden a sus habilidades actuales y prioridades sociales."}]}]},"forms":{"eyebrow":"Formularios","title":"Descargue formularios de admisión y referencia","intro":"Elija el formulario que corresponda a su servicio, descárguelo, imprímalo y complételo antes de su cita de admisión.","steps":["Elija el formulario para su servicio","Descárguelo e imprímalo","Complételo y devuélvalo a VTCC"],"assistanceText":"¿Necesita ayuda? Llame al {phone}.","insuranceTitle":"Seguro y financiamiento","insuranceBody":"VTCC acepta clientes con Medicaid o financiamiento del condado. Contacte su oficina local o estatal de Medicaid para verificar la cobertura de su hijo, o llame a VTCC para obtener ayuda con la verificación.","insuranceLinkLabel":"Más información sobre seguro y financiamiento","insuranceLinkHref":"/insurance","categories":[{"title":"Admisiones","intro":"Descargue, imprima y complete el formulario de admisión y cuestionario que corresponda al servicio que solicita.","items":[{"id":"abaIntake","title":"Formulario de admisión de VTCC para servicios ABA y cuestionario para fuentes de referencia"},{"id":"faptReferralQuestionnaire","title":"Cuestionario para fuentes de referencia de visitas supervisadas y/o servicios FAPT"}]},{"title":"Derechos del cliente","intro":"La seguridad, los derechos y la privacidad de nuestros clientes y familias son nuestra prioridad. Este aviso se revisa con cada cliente en presencia de sus padres o tutores antes de iniciar cualquier servicio de VTCC.","items":[{"id":"clientRightsEnglish","title":"It is Your Right (English)"},{"id":"clientRightsSpanish","title":"It is Your Right (Español)"}]}]},"about":{"eyebrow":"Acerca de VTCC","title":"Nuestro equipo y nuestra misión","intro":"VTCC brinda servicios de salud mental y conductual culturalmente responsivos para niños, adolescentes y familias en el norte de Virginia.","items":["Misión y atención multicultural/transcultural","Biografía del director y liderazgo clínico","Biografías de BCBA/RBT o terapeutas cuando estén aprobadas","Ubicaciones de oficinas en Fairfax y Fredericksburg"]},"contact":{"eyebrow":"Contacto","title":"Solicite servicios o haga una pregunta de referencia","intro":"¿Tiene preguntas sobre servicios, referencias, seguro o próximos pasos? Contacte a VTCC y un miembro del equipo puede orientarlo.","callEyebrow":"Llame a VTCC","callTitle":"¿Prefiere hablar con alguien?","callIntro":"Elija la oficina más cercana a usted. Un miembro del equipo puede ayudar con servicios, preguntas de referencia y próximos pasos."},"contactFamily":{"eyebrow":"For families","title":"Request services for your child","intro":"Tell us how to reach you and a little about your child. A VTCC team member can explain intake steps, forms, and funding review.","callEyebrow":"Call VTCC","callTitle":"Prefer to talk with someone?","callIntro":"Choose the office closest to you. A team member can help with services, paperwork, and next steps."},"contactReferral":{"eyebrow":"For referrers","title":"Start a referral or ask about eligibility","intro":"Schools, doctors, case managers, county partners, and community professionals can use this form to ask about referral requirements. Do not send protected health information here.","callEyebrow":"Call VTCC","callTitle":"Need to discuss a referral by phone?","callIntro":"Choose the office closest to the family. A team member can help with eligibility, required paperwork, and next steps."},"careers":{"eyebrow":"Carreras en VTCC","title":"Aporte sus fortalezas a un trabajo que importa","intro":"Únase a un equipo que ayuda a niños, adolescentes y familias a avanzar con atención práctica, respetuosa y culturalmente responsiva.","applyLabel":"Solicitar empleo","applyHref":"/career/apply","overviewLabel":"Explore oportunidades","pillars":[{"title":"Las personas primero","body":"Nos apoyamos para que cada miembro del equipo pueda hacer un trabajo cuidadoso y confiable."},{"title":"Atención culturalmente responsiva","body":"Escuchamos a las familias y colegas, respetamos sus experiencias y damos espacio a distintas perspectivas."},{"title":"Espacio para crecer","body":"Valoramos la supervisión, la colaboración y el desarrollo constante en cada etapa profesional."}],"opportunity":{"eyebrow":"Por qué trabajar con VTCC","title":"Un lugar de trabajo enfocado en el progreso significativo","body":"Nuestro trabajo se basa en las relaciones. Buscamos personas que aporten cuidado profesional, curiosidad y respeto a cada interacción.","items":["Colabore con un equipo multidisciplinario","Apoye a niños, adolescentes y familias en el norte de Virginia","Aprenda mediante supervisión, comentarios y resolución compartida de problemas","Contribuya a una organización en crecimiento con una misión comunitaria clara"]},"steps":{"eyebrow":"Qué puede esperar","title":"Un camino claro desde la solicitud hasta la conversación","intro":"Queremos que el proceso sea claro, respetuoso y valioso para su tiempo.","items":[{"title":"Comparta su experiencia","body":"Cuéntenos sobre su experiencia, intereses y el tipo de trabajo que espera realizar."},{"title":"Conozca al equipo","body":"Si su experiencia coincide con una oportunidad, le invitaremos a conversar."},{"title":"Hablemos del puesto","body":"Conversaremos sobre responsabilidades, apoyo, disponibilidad y próximos pasos."}]},"closing":{"title":"¿Listo para dar el siguiente paso?","body":"Envíe una solicitud de muestra para conocer la información que VTCC pediría a futuros candidatos.","buttonLabel":"Solicitar empleo"}},"earlyLearners":{"eyebrow":"Programa de Primeros Aprendices","title":"Desarrolle confianza para la escuela y los entornos sociales","intro":"El programa de Primeros Aprendices apoya a niños en edad preescolar mientras practican rutinas, comunicación, juego y habilidades de aprendizaje temprano que les ayudan a participar en la escuela y en entornos sociales.","columns":[{"title":"Lo que apoya el programa","items":["Rutinas y transiciones para la preparación escolar","Comunicación y habilidades de aprendizaje temprano","Juego, participación y conexión social","Seguir instrucciones y desarrollar independencia"]},{"title":"Cómo participan las familias","items":["Metas individualizadas según las fortalezas y necesidades del niño","Práctica en rutinas y entornos conocidos","Colaboración y orientación para cuidadores","Seguimiento del progreso y ajustes al plan"]}]},"feedingProgram":{"eyebrow":"Programa de Alimentación","title":"Haga que las comidas sean más flexibles y exitosas","intro":"El Programa de Alimentación utiliza prácticas ABA para ayudar a los niños a ampliar su repertorio y sus preferencias alimentarias mediante metas individualizadas, apoyo positivo y práctica gradual.","columns":[{"title":"Lo que puede apoyar el programa","items":["Ampliar la variedad de alimentos que acepta el niño","Desarrollar comodidad con nuevos sabores, texturas y presentaciones","Apoyar rutinas positivas durante las comidas","Practicar preferencias alimentarias flexibles a un ritmo manejable"]},{"title":"Cómo se planifica el apoyo","items":["Evaluación de los patrones actuales y las prioridades familiares","Metas individualizadas y refuerzo positivo","Colaboración con cuidadores durante las comidas cotidianas","Seguimiento del progreso y ajustes según la respuesta del niño"]}]},"socialSkillsGroup":{"eyebrow":"Grupo de Habilidades Sociales","title":"Practique habilidades sociales avanzadas con compañeros","intro":"El Grupo de Habilidades Sociales es para clientes que están listos para trabajar en habilidades sociales más avanzadas, incluyendo la comprensión del sarcasmo, la conversación y el juego apropiado para su edad con compañeros.","columns":[{"title":"Habilidades que puede abordar el grupo","items":["Comprender el sarcasmo, el humor y los significados implícitos","Conversación de ida y vuelta y pensamiento flexible","Juego y actividades compartidas apropiadas para la edad","Unirse a grupos, resolver problemas y reparar malentendidos"]},{"title":"Un entorno grupal con apoyo","items":["Práctica en grupos pequeños con metas individualizadas","Orientación y comentarios positivos del personal capacitado","Oportunidades para practicar habilidades en interacciones realistas","Colaboración familiar para apoyar la práctica fuera del grupo"]}]}},"careerApplication":{"eyebrow":"Solicite empleo en VTCC","title":"Cuéntenos cómo puede contribuir","intro":"Esta es una vista previa del futuro proceso de solicitud. Su información permanece en este navegador y no se envía a VTCC.","privacyTitle":"La privacidad importa","privacyNote":"No cargue expedientes clínicos, información de clientes, números de Seguro Social ni otros documentos confidenciales. Una plataforma de producción usaría un proceso seguro aprobado.","selectPlaceholder":"Seleccione una opción","submitLabel":"Revisar solicitud","backLabel":"Volver a Carreras","backHref":"/career","consentLabel":"Entiendo que esta es una vista previa y que mi información no se enviará.","fileLabel":"Currículum o documento de apoyo","fileRequiredMessage":"Adjunte un currículum o documento de apoyo.","fileTypes":".pdf,.doc,.docx,.txt","fileAcceptLabel":"Tipos de archivo aceptados","fields":[{"name":"fullName","label":"Nombre completo","type":"text","autocomplete":"name"},{"name":"email","label":"Correo electrónico","type":"email","autocomplete":"email"},{"name":"phone","label":"Número de teléfono","type":"tel","autocomplete":"tel"},{"name":"role","label":"Puesto de interés","type":"select","options":["Técnico de conducta registrado","Analista de conducta certificado por la junta","Profesional clínico de programas","Administración u operaciones","Otro"]},{"name":"location","label":"Ciudad y estado","type":"text","autocomplete":"address-level2"},{"name":"workAuthorization","label":"¿Tiene autorización para trabajar en Estados Unidos?","type":"select","options":["Sí","No","Me gustaría hablar sobre esto"]},{"name":"experience","label":"Experiencia relevante","type":"textarea","rows":4},{"name":"coverLetter","label":"¿Qué le interesa de trabajar con VTCC?","type":"textarea","rows":5}]},"form":{"notice":"No incluya detalles médicos privados, informes de diagnóstico, números de Seguro Social ni inquietudes urgentes de seguridad en este formulario. Si se trata de una emergencia, llame al 911 o vaya a la sala de emergencias más cercana.","consentLabel":"Entiendo que este formulario no es para emergencias ni detalles médicos sensibles.","submitLabel":"Enviar Solicitud","fields":[{"name":"name","label":"Nombre del padre/tutor o referente","type":"text","autocomplete":"name"},{"name":"email","label":"Correo electrónico","type":"email","autocomplete":"email"},{"name":"phone","label":"Teléfono","type":"tel","autocomplete":"tel"},{"name":"preferredContact","label":"Método de contacto preferido","type":"select","options":["Teléfono","Correo electrónico","Cualquiera"]},{"name":"ageRange","label":"Rango de edad del niño","type":"select","options":["0-2","3-5","6-8","9-11","12-14","15-17","18+","No aplica"]},{"name":"service","label":"Interés en servicios","type":"select","options":["ABA","Primeros Aprendices","Programa de Alimentación","Grupo de Habilidades Sociales","No estoy seguro","Pregunta de referencia"]},{"name":"funding","label":"Fuente de financiamiento","type":"select","options":["Medicaid","MCO","Seguro comercial","Condado/FAPT","No estoy seguro"]},{"name":"location","label":"Ciudad o condado","type":"text"},{"name":"message","label":"Mensaje breve no sensible","type":"textarea","rows":4}]},"formFamily":{"notice":"Please do not include private medical details, diagnosis reports, Social Security numbers, or urgent safety concerns in this form. If this is an emergency, call 911 or go to the nearest emergency room.","consentLabel":"I understand this form is not for emergencies or sensitive medical details.","submitLabel":"Submit service request","fields":[{"name":"name","label":"Parent or guardian name","type":"text","autocomplete":"name"},{"name":"email","label":"Email","type":"email","autocomplete":"email"},{"name":"phone","label":"Phone","type":"tel","autocomplete":"tel"},{"name":"preferredContact","label":"Preferred contact method","type":"select","options":["Phone","Email","Either"]},{"name":"ageRange","label":"Child's age range","type":"select","options":["0-2","3-5","6-8","9-11","12-14","15-17","18+"]},{"name":"service","label":"Service you are interested in","type":"select","options":["ABA","Primeros Aprendices","Programa de Alimentación","Grupo de Habilidades Sociales","Aún no estoy seguro"]},{"name":"funding","label":"Funding source (if known)","type":"select","options":["Medicaid","MCO","Commercial insurance","County/FAPT","Not sure"]},{"name":"location","label":"City or county","type":"text"},{"name":"message","label":"What would you like help with?","type":"textarea","rows":4}]},"formReferral":{"notice":"Please do not include diagnosis reports, IEPs, treatment records, Social Security numbers, or urgent safety concerns in this form. Use VTCC's approved secure process for referral documents. If this is an emergency, call 911.","consentLabel":"I understand this form is for referral questions only and is not for emergencies or protected health information.","submitLabel":"Submit referral inquiry","fields":[{"name":"name","label":"Referrer name","type":"text","autocomplete":"name"},{"name":"organization","label":"Organization or agency","type":"text"},{"name":"role","label":"Your role","type":"select","options":["School staff","Physician or nurse","Therapist or counselor","Case manager","County or FAPT partner","Other community professional"]},{"name":"email","label":"Work email","type":"email","autocomplete":"email"},{"name":"phone","label":"Work phone","type":"tel","autocomplete":"tel"},{"name":"preferredContact","label":"Preferred contact method","type":"select","options":["Phone","Email","Either"]},{"name":"parentName","label":"Parent or guardian name (if known)","type":"text"},{"name":"parentPhone","label":"Parent or guardian phone (if known)","type":"tel","autocomplete":"tel"},{"name":"ageRange","label":"Child's age range","type":"select","options":["0-2","3-5","6-8","9-11","12-14","15-17","18+","Not sure"]},{"name":"service","label":"Service requested","type":"select","options":["ABA","Primeros Aprendices","Programa de Alimentación","Grupo de Habilidades Sociales","Aún no estoy seguro"]},{"name":"funding","label":"Funding source (if known)","type":"select","options":["Medicaid","MCO","Commercial insurance","County/FAPT","Not sure"]},{"name":"location","label":"Child's city or county","type":"text"},{"name":"message","label":"Reason for referral (non-sensitive summary only)","type":"textarea","rows":4}]},"offices":[{"name":"Oficina de Fairfax","street":"10565 Fairfax Boulevard, Suite 300","city":"Fairfax, VA 22030","phone":"703.218.6599","phoneHref":"tel:17032186599","fax":"703.891.7167"},{"name":"Oficina de Fredericksburg","street":"3920 Plank Road, Suite 220","city":"Fredericksburg, VA 22407","phone":"540.412.9969","phoneHref":"tel:15404129969","fax":"703.891.7167"}],"footer":{"text":"Prototipo de mejora del sitio web de Victoria Transcultural Clinical Center.","links":[{"label":"Servicios","href":"/#services"},{"label":"Seguro","href":"/insurance"},{"label":"Preguntas y Guías","href":"/resources"},{"label":"Contacto","href":"/contact"}]},"pages":{"abaTherapy":{"title":"Página de Terapia ABA","hero":{"headline":"Terapia ABA diseñada en torno a cada niño","body":"El Análisis de Conducta Aplicado es un enfoque basado en evidencia que utiliza estrategias positivas para ayudar a los niños a desarrollar habilidades significativas. VTCC crea planes ABA individualizados según la evaluación, la aportación familiar y las fortalezas y necesidades de cada niño.","buttons":["Solicitar servicios de ABA","Llamar sobre ABA"]},"sections":[{"title":"Lo que la ABA puede apoyar","items":["Comunicación","Interacción social","Rutinas de vida diaria","Preparación escolar","Habilidades de juego y ocio","Regulación emocional y conductual","Conductas de reemplazo más seguras","Práctica de habilidades con apoyo del cuidador en el hogar"],"note":"Cada niño es diferente. VTCC diseña metas según la evaluación, la observación, la aportación del cuidador y las recomendaciones clínicas."},{"title":"Cómo VTCC brinda ABA","steps":["Un Analista de Conducta Certificado por la Junta (BCBA) revisa las necesidades del niño.","La familia comparte información sobre fortalezas, desafíos, rutinas y prioridades.","El BCBA crea metas de tratamiento y un plan de apoyo conductual cuando corresponda.","Técnicos de conducta o terapeutas pueden brindar servicios directos bajo supervisión del BCBA.","Los padres y cuidadores reciben orientación para practicar habilidades en las rutinas diarias.","Se monitorea el progreso y se actualizan los planes a medida que el niño crece."]},{"title":"Capacitación para padres","body":"Los padres y cuidadores son socios esenciales en la terapia ABA. VTCC apoya a las familias con estrategias que pueden usar durante rutinas diarias, transiciones, momentos de comunicación y situaciones difíciles."}],"cta":{"body":"¿No está seguro de si la ABA es la opción adecuada? Contacte a VTCC y nuestro equipo puede explicar el proceso de admisión, los requisitos de financiamiento y los próximos pasos.","button":"Preguntar sobre servicios de ABA"}},"earlyLearners":{"title":"Página del Programa de Primeros Aprendices","hero":{"headline":"Apoyo para el aprendizaje temprano y la preparación social","body":"El programa de Primeros Aprendices apoya a niños en edad preescolar mientras practican rutinas, comunicación, juego y habilidades de aprendizaje temprano para la escuela y los entornos sociales.","buttons":["Solicitar servicios de Primeros Aprendices","Preguntar sobre elegibilidad"]},"sections":[{"title":"Lo que pueden practicar los primeros aprendices","intro":"Las metas pueden incluir transiciones, instrucciones, comunicación, juego, participación social, aprendizaje temprano e independencia.","items":["Rutinas y transiciones para la preparación escolar","Comunicación y habilidades de aprendizaje temprano","Juego, participación y conexión social","Seguir instrucciones y desarrollar independencia"]},{"title":"Colaboración con la familia","body":"VTCC trabaja con los cuidadores para identificar metas significativas y practicar habilidades en las rutinas cotidianas. Los planes se ajustan a medida que el niño crece y desarrolla confianza."}],"cta":{"body":"Contacte a VTCC para preguntar si el programa de Primeros Aprendices puede ser adecuado para su hijo en edad preescolar y conocer los próximos pasos de admisión.","button":"Preguntar sobre Primeros Aprendices"}},"feedingProgram":{"title":"Página del Programa de Alimentación","hero":{"headline":"Apoyo para ampliar el repertorio alimentario","body":"El Programa de Alimentación utiliza prácticas ABA para ayudar a los niños a ampliar su repertorio y sus preferencias alimentarias mediante metas individualizadas, apoyo positivo y práctica gradual.","buttons":["Solicitar servicios de alimentación","Preguntar sobre elegibilidad"]},"sections":[{"title":"Lo que puede apoyar el programa de alimentación","intro":"El programa ayuda a los niños a practicar la aceptación y exploración de una mayor variedad de alimentos, sabores, texturas y presentaciones.","items":["Ampliar la variedad de alimentos que acepta el niño","Desarrollar comodidad con nuevos sabores y texturas","Apoyar rutinas positivas durante las comidas","Practicar preferencias alimentarias flexibles a un ritmo manejable"]},{"title":"Práctica positiva e individualizada","body":"El equipo colabora con los cuidadores para establecer metas prácticas, usar apoyo positivo e introducir la práctica a un ritmo que respete las necesidades del niño y las rutinas familiares."}],"cta":{"body":"Contacte a VTCC para preguntar si el Programa de Alimentación puede ser apropiado para su hijo y conocer el proceso de admisión.","button":"Preguntar sobre el Programa de Alimentación"}},"socialSkillsGroup":{"title":"Página del Grupo de Habilidades Sociales","hero":{"headline":"Desarrolle habilidades sociales avanzadas con compañeros","body":"El Grupo de Habilidades Sociales es para clientes que están listos para practicar habilidades sociales más avanzadas, como comprender el sarcasmo, conversar y participar en juegos apropiados para su edad con compañeros.","buttons":["Solicitar servicios del grupo social","Preguntar sobre elegibilidad"]},"sections":[{"title":"Lo que puede practicar el grupo","intro":"Los clientes reciben orientación y comentarios mientras practican interacciones realistas con compañeros.","items":["Comprender el sarcasmo, el humor y los significados implícitos","Conversación de ida y vuelta y pensamiento flexible","Juego y actividades compartidas apropiadas para la edad","Unirse a grupos, resolver problemas y reparar malentendidos"]},{"title":"Aprendizaje mediante práctica con apoyo","body":"Los clientes reciben orientación y comentarios mientras practican interacciones realistas con compañeros. Las metas son individualizadas y apoyan la práctica en la escuela, la comunidad y otros entornos sociales."}],"cta":{"body":"Contacte a VTCC para preguntar si el Grupo de Habilidades Sociales puede ser adecuado para su hijo y conocer la disponibilidad actual.","button":"Preguntar sobre el Grupo de Habilidades Sociales"}},"insuranceFunding":{"title":"Página de Seguro y Financiamiento","hero":{"headline":"Orientación sobre seguro y financiamiento","body":"Entender la cobertura puede resultar confuso. VTCC ayuda a familias y socios de referencia a revisar las vías de financiamiento disponibles e identificar qué información puede necesitarse antes de comenzar los servicios."},"sections":[{"title":"Vías de financiamiento","body":"El sitio público actual de VTCC hace referencia a Medicaid, organizaciones de atención administrada, planes comerciales y financiamiento del condado/FAPT. Antes de publicar esta página, el liderazgo debe confirmar los planes aceptados exactos y los requisitos de financiamiento para cada servicio."},{"title":"Proceso de verificación","intro":"Las familias pueden ayudar preparando:","items":["Nombre completo y fecha de nacimiento del niño","Información de contacto del padre o tutor","Tarjeta de seguro o fuente de financiamiento","Servicio solicitado","Documentos de referencia, si se requieren","Documentación de diagnóstico o clínica solo si se solicita mediante un proceso seguro aprobado"]},{"title":"Nota importante","body":"La cobertura y la elegibilidad varían según el servicio, el plan, los requisitos de autorización y la fuente de financiamiento. VTCC puede ayudar a verificar la información, pero las decisiones finales de cobertura pueden depender del plan de seguro, la organización de atención administrada o la agencia de financiamiento."}],"cta":"Preguntar sobre seguro y financiamiento"},"forReferrers":{"title":"Página para Referentes","hero":{"headline":"Referir un niño o una familia a VTCC","body":"VTCC recibe referencias apropiadas de familias, escuelas, pediatras, terapeutas, administradores de casos, socios del condado y profesionales comunitarios."},"sections":[{"title":"Información de referencia a incluir","intro":"Para ayudar a VTCC a responder con eficiencia, se puede solicitar a los referentes:","items":["Nombre y edad del niño o adolescente","Información de contacto del padre o tutor","Servicio solicitado","Motivo de la referencia","Fuente de financiamiento o información del seguro","Documentación de referencia relevante","Urgencia o preocupaciones de seguridad, si corresponde"],"note":"No envíe documentos sensibles a través de un formulario o correo electrónico no seguro a menos que VTCC haya proporcionado un método seguro aprobado."}],"cta":{"body":"¿Preguntas sobre elegibilidad o si la referencia es adecuada? Contacte a VTCC antes de enviar documentos.","button":"Iniciar una referencia"}},"resourcesFaq":{"title":"Página de Recursos / Preguntas Frecuentes","hero":{"headline":"Recursos para familias y socios de referencia","body":"VTCC ofrece recursos educativos para ayudar a las familias a entender la terapia ABA, el programa de Primeros Aprendices, el Programa de Alimentación, el Grupo de Habilidades Sociales, la participación de los padres, los pasos de admisión y las preguntas sobre financiamiento."},"faqs":[{"question":"¿Qué servicios brinda VTCC?","answer":"VTCC brinda terapia ABA, un programa de Primeros Aprendices, un Programa de Alimentación y un Grupo de Habilidades Sociales para niños y familias. Los servicios dependen de la elegibilidad, el financiamiento, la necesidad clínica y la disponibilidad."},{"question":"¿Qué es el programa de Primeros Aprendices?","answer":"Es un programa para niños en edad preescolar que se enfoca en desarrollar comunicación, juego, rutinas y habilidades de aprendizaje temprano para ayudarles a participar en la escuela y en entornos sociales."},{"question":"¿Qué apoya el Programa de Alimentación?","answer":"El Programa de Alimentación utiliza prácticas ABA para ayudar a los niños a ampliar gradualmente su repertorio y sus preferencias alimentarias mediante metas individualizadas, apoyo positivo y colaboración con los cuidadores."},{"question":"¿Quién puede beneficiarse del Grupo de Habilidades Sociales?","answer":"El Grupo de Habilidades Sociales es para clientes que están listos para practicar habilidades sociales más avanzadas, como comprender el sarcasmo, conversar y participar en juegos apropiados para su edad con compañeros."},{"question":"¿Dónde brinda servicios VTCC?","answer":"Los servicios pueden brindarse en entornos individuales y grupales según el programa, el plan de tratamiento y la disponibilidad. Contacte a VTCC para confirmar las opciones actuales para su ubicación."},{"question":"¿VTCC acepta seguros?","answer":"Los materiales actuales enumeran varios pagadores de Medicaid, atención administrada y comerciales, y también hacen referencia al financiamiento del condado/FAPT. Contacte a VTCC para verificar la cobertura actual para su plan y servicio."},{"question":"¿Qué es la terapia ABA?","answer":"La ABA es un enfoque basado en evidencia que utiliza estrategias positivas para ayudar a los niños a desarrollar habilidades y reducir conductas que interfieren con el aprendizaje, la seguridad o la vida diaria."},{"question":"¿Participan los padres?","answer":"Sí. La participación de padres y cuidadores es una parte importante de los servicios individualizados y ayuda a los niños a practicar habilidades en las rutinas diarias."},{"question":"¿Cómo empiezo?","answer":"Llame a VTCC o complete el formulario de solicitud. El equipo puede explicar qué programa puede ser adecuado, los formularios requeridos, la revisión de financiamiento, la admisión, la evaluación y la programación."},{"question":"¿Pueden los profesionales referir a un niño?","answer":"Sí. Escuelas, médicos, administradores de casos, socios del condado y otros profesionales pueden contactar a VTCC para preguntar sobre los requisitos de referencia."}]}},"compliance":{"contentApproval":"El liderazgo debe revisar y aprobar todo el lenguaje final de servicios, elegibilidad, seguro y cumplimiento.","formSecurity":"No recopile informes de diagnóstico, detalles clínicos ni información de salud protegida a través de un formulario de contacto normal a menos que VTCC confirme que el formulario es seguro, aprobado y conforme."},"home":{"processTeaser":{"linkLabel":"Ver la ruta completa de admisión","linkHref":"/get-started"},"resourcesTeaser":{"title":"Guías y preguntas frecuentes","intro":"Explore temas comunes sobre admisión, financiamiento, terapia ABA, programas especializados y referencias.","linkLabel":"Ver preguntas y guías","linkHref":"/resources"}}}}};
